// Сгенерировано tools/build.py из course/<язык>/*.txt. Не редактируй вручную.
(window.RK_DATA = window.RK_DATA || {})["pro-ru"] = {"modules":[{"id":"a00","title":"Мост от основ","sub":"Короткая проверка: всё ли на месте перед вторым уровнем","lessons":[{"id":"a00-1","title":"Как устроен второй уровень","min":5,"cards":[{"t":"text","title":"Добро пожаловать на второй уровень","md":"Ты прошёл основы. Теперь пойдём **глубже**: как устроены трейты, итераторы, потоки, async, макросы и `unsafe`.\n\nПравила те же:\n- Один урок — одна идея.\n- Короткие шаги. Жми «Дальше» в своём темпе.\n- Карточки «Углубиться» можно пропускать. Они для тех, кому интересно «а как оно внутри».\n\n> **Аналогия:** первый уровень — ты научился водить. Второй — открываешь капот и смотришь, как работает мотор."},{"t":"text","title":"Что будет немного иначе","md":"- Примеры длиннее. Иногда 20–30 строк. Читай их сверху вниз, по кусочку.\n- Иногда нужны **крейты** (чужие библиотеки): `tokio`, `serde`, `rayon`. Rust Playground их уже знает, ставить ничего не надо.\n- Больше задач, где нужно не «напечатать строку», а написать кусок настоящей программы."},{"t":"text","title":"Если стало тяжело","md":"Это нормально. Темы второго уровня сложнее. Что помогает:\n- Вернуться в урок первого уровня по той же теме. Ссылки на них будут в тексте.\n- Сделать перерыв и пройти урок завтра. Прогресс сохранится.\n- Запустить пример и поменять в нём одну вещь. Посмотреть, что изменится."},{"t":"quiz","md":"Что делать с карточкой «Углубиться», если сейчас не интересно?","options":["Обязательно прочитать, иначе дальше не пустит","Нажать «Дальше» и пропустить","Начать урок заново"],"answer":1,"why":["Нет, она необязательная.","Верно. К ней можно вернуться потом.","Не нужно."]},{"t":"recap","items":["Второй уровень — тот же формат, темы глубже.","Крейты в Playground уже есть.","Тяжело — вернись к основам или сделай перерыв."]}],"goals":["Понять, чем второй уровень отличается от первого","Узнать, что делать, если стало тяжело"]},{"id":"a00-2","title":"Повторяем: владение и заимствование","min":7,"cards":[{"t":"text","title":"Три правила владения","md":"1. У каждого значения есть **владелец** — одна переменная.\n2. Владелец может быть только **один**.\n3. Владелец ушёл из области видимости — значение удаляется.\n\nЕсли забыл подробности — урок первого уровня «Владение»."},{"t":"code","code":"fn main() {\n    let a = String::from(\"кот\");\n    let b = a; // владение переехало в b\n    println!(\"{b}\");\n}","out":"кот","after":"После `let b = a;` переменной `a` пользоваться нельзя. Попробуй добавить `println!(\"{a}\");` и запусти."},{"t":"text","title":"Заимствование","md":"- `&x` — дать **посмотреть**. Таких ссылок может быть сколько угодно.\n- `&mut x` — дать **поменять**. Такая ссылка может быть только **одна**, и пока она есть — других нет.\n\n> **Аналогия:** книгу в библиотеке могут читать многие. Но исправлять её можно, только когда она у тебя одного в руках."},{"t":"quiz","md":"Сколько изменяемых ссылок `&mut` на одно значение может быть одновременно?","options":["Сколько угодно","Одна","Ноль, их нельзя создавать"],"answer":1,"why":["Это про `&`.","Верно. И пока она жива, обычных `&` тоже нет.","Можно, если переменная объявлена с `mut`."]},{"t":"fill","explain":"Чтобы менять чужое значение, функция берёт `&mut String`, а при вызове пишем `&mut word`.","md":"Заполни пропуски, чтобы функция поменяла строку, а `main` её напечатал.","code":"fn shout(s: ___ String) {\n    s.push('!');\n}\n\nfn main() {\n    let mut word = String::from(\"ура\");\n    shout(___ word);\n    println!(\"{word}\");\n}","answers":[["&mut"],["&mut"]]},{"t":"task","md":"Функция `longest` должна вернуть длину самой длинной строки из списка. Она не должна забирать список себе: после вызова `main` печатает его ещё раз.","code":"fn longest(words: Vec<String>) -> usize {\n    let mut best = 0;\n    for w in words {\n        if w.len() > best {\n            best = w.len();\n        }\n    }\n    best\n}\n\nfn main() {\n    let words = vec![String::from(\"кот\"), String::from(\"hello\"), String::from(\"Rust\")];\n    println!(\"{}\", longest(words));\n    println!(\"{}\", words.len());\n}","solution":"fn longest(words: &[String]) -> usize {\n    let mut best = 0;\n    for w in words {\n        if w.len() > best {\n            best = w.len();\n        }\n    }\n    best\n}\n\nfn main() {\n    let words = vec![String::from(\"кот\"), String::from(\"hello\"), String::from(\"Rust\")];\n    println!(\"{}\", longest(&words));\n    println!(\"{}\", words.len());\n}","expect":"6\n3","hints":["Пусть функция берёт ссылку: `words: &[String]`, а вызов будет `longest(&words)`.","«кот» — это 6 байт, потому что русские буквы занимают по 2 байта. `len()` считает байты."]},{"t":"recap","items":["Один владелец. Передал — значение переехало.","`&` — смотреть (много), `&mut` — менять (одна).","Функциям обычно дают ссылку, а не само значение."]}],"goals":["Вспомнить три правила владения","Вспомнить разницу между `&` и `&mut`"]},{"id":"a00-3","title":"Повторяем: enum, Result, трейты","min":7,"cards":[{"t":"text","title":"enum и match","md":"`enum` — «одно из нескольких». `match` — разобрать все варианты.\n\n```\nenum Light { Red, Yellow, Green }\n\nfn action(l: Light) -> &'static str {\n    match l {\n        Light::Red => \"стой\",\n        Light::Yellow => \"жди\",\n        Light::Green => \"иди\",\n    }\n}\n```\n`match` должен покрыть **все** варианты. Забыл один — компилятор напомнит."},{"t":"text","title":"Result и ?","md":"`Result<T, E>` — либо `Ok(значение)`, либо `Err(ошибка)`.\n\nЗнак `?` после вызова значит: «если ошибка — сразу верни её наверх, если успех — достань значение»."},{"t":"code","code":"fn double(text: &str) -> Result<i32, std::num::ParseIntError> {\n    let n: i32 = text.parse()?;\n    Ok(n * 2)\n}\n\nfn main() {\n    println!(\"{:?}\", double(\"21\"));\n    println!(\"{}\", double(\"кот\").is_err());\n}","out":"Ok(42)\ntrue"},{"t":"text","title":"Трейт — умение","md":"Трейт описывает, **что умеет** тип. Например, `Display` — «умею печататься через `{}`».\n\n```\ntrait Speak {\n    fn speak(&self) -> String;\n}\n```\nЛюбой тип может реализовать трейт через `impl Speak for Тип`."},{"t":"quiz","md":"Что делает `?` после `text.parse()`?","options":["Печатает ошибку и продолжает","При ошибке выходит из функции и возвращает её, при успехе отдаёт значение","Превращает ошибку в 0"],"answer":1,"why":["Нет, он возвращает ошибку из функции.","Верно.","Так делает `unwrap_or(0)`."]},{"t":"task","md":"Реализуй трейт `Speak` для `Cat` и `Dog`. Кот говорит `Мяу`, собака — `Гав`.","code":"trait Speak {\n    fn speak(&self) -> String;\n}\n\nstruct Cat;\nstruct Dog;\n\n// твой код\n\nfn main() {\n    println!(\"{}\", Cat.speak());\n    println!(\"{}\", Dog.speak());\n}","solution":"trait Speak {\n    fn speak(&self) -> String;\n}\n\nstruct Cat;\nstruct Dog;\n\nimpl Speak for Cat {\n    fn speak(&self) -> String {\n        String::from(\"Мяу\")\n    }\n}\n\nimpl Speak for Dog {\n    fn speak(&self) -> String {\n        String::from(\"Гав\")\n    }\n}\n\nfn main() {\n    println!(\"{}\", Cat.speak());\n    println!(\"{}\", Dog.speak());\n}","expect":"Мяу\nГав","hints":["Начни так: `impl Speak for Cat { fn speak(&self) -> String { ... } }`."]},{"t":"recap","items":["`enum` + `match` — разбор всех вариантов.","`Result` + `?` — ошибки идут наверх сами.","Трейт — набор умений, `impl Трейт for Тип` — научить тип."]}],"goals":["Вспомнить `match` по `enum`","Вспомнить `Result` и `?`","Вспомнить, что такое трейт"]},{"id":"a00-p","title":"Практика: разминка","min":12,"cards":[{"t":"task","md":"Найди в списке первое число больше 10 и напечатай его. Если такого нет — напечатай `нет`.","code":"fn main() {\n    let nums = vec![3, 8, 15, 4, 22];\n    // твой код\n}","solution":"fn main() {\n    let nums = vec![3, 8, 15, 4, 22];\n    match nums.iter().find(|&&n| n > 10) {\n        Some(n) => println!(\"{n}\"),\n        None => println!(\"нет\"),\n    }\n}","expect":"15","hints":["У итератора есть метод `find`. Он возвращает `Option`.","`nums.iter().find(|&&n| n > 10)` — двойной `&`, потому что `find` даёт ссылку на ссылку."]},{"t":"task","md":"Структура `Item` хранит название и цену в копейках. Посчитай общую сумму корзины и напечатай её в рублях с двумя знаками: `Итого: 377.50`.","code":"struct Item {\n    name: String,\n    cents: u32,\n}\n\nfn main() {\n    let cart = vec![\n        Item { name: String::from(\"хлеб\"), cents: 5500 },\n        Item { name: String::from(\"сыр\"), cents: 25000 },\n        Item { name: String::from(\"чай\"), cents: 7250 },\n    ];\n    // твой код\n}","solution":"struct Item {\n    name: String,\n    cents: u32,\n}\n\nfn main() {\n    let cart = vec![\n        Item { name: String::from(\"хлеб\"), cents: 5500 },\n        Item { name: String::from(\"сыр\"), cents: 25000 },\n        Item { name: String::from(\"чай\"), cents: 7250 },\n    ];\n    let total: u32 = cart.iter().map(|i| i.cents).sum();\n    println!(\"Итого: {}.{:02}\", total / 100, total % 100);\n}","expect":"Итого: 377.50","hints":["`cart.iter().map(|i| i.cents).sum()` — сумма. Тип укажи явно: `let total: u32 = ...`.","Рубли — `total / 100`, копейки — `total % 100`. `{:02}` дописывает ноль слева: `5` → `05`."]},{"t":"task","md":"Функция `parse_age` превращает текст в возраст. Пустая строка — ошибка `\"пусто\"`, не число — ошибка `\"не число\"`. Используй `?` или `match`.","code":"fn parse_age(text: &str) -> Result<u32, String> {\n    // твой код\n}\n\nfn main() {\n    println!(\"{:?}\", parse_age(\"30\"));\n    println!(\"{:?}\", parse_age(\"\"));\n    println!(\"{:?}\", parse_age(\"тридцать\"));\n}","solution":"fn parse_age(text: &str) -> Result<u32, String> {\n    if text.is_empty() {\n        return Err(String::from(\"пусто\"));\n    }\n    text.parse::<u32>().map_err(|_| String::from(\"не число\"))\n}\n\nfn main() {\n    println!(\"{:?}\", parse_age(\"30\"));\n    println!(\"{:?}\", parse_age(\"\"));\n    println!(\"{:?}\", parse_age(\"тридцать\"));\n}","expect":"Ok(30)\nErr(\"пусто\")\nErr(\"не число\")","hints":["Сначала проверь `text.is_empty()` и верни `Err(...)`.","`map_err(|_| ...)` заменяет одну ошибку на другую."]},{"t":"recap","items":["`find` ищет первое подходящее и возвращает `Option`.","`map` + `sum` считают итог за одну строку.","`map_err` меняет тип ошибки."]}],"practice":true,"goals":["Размять руки перед вторым уровнем","Собрать вместе структуры, `Vec`, `Option` и итераторы"]}]},{"id":"a01","title":"Трейты глубже","sub":"Методы по умолчанию, dyn, ассоциированные типы, операторы","lessons":[{"id":"a01-1","title":"Методы по умолчанию и трейт над трейтом","min":7,"cards":[{"t":"text","title":"Метод по умолчанию","md":"В трейте можно не только объявить метод, но и **сразу написать** его тело. Тогда типу не обязательно его реализовывать.\n\n```\ntrait Greet {\n    fn name(&self) -> String;          // обязательно\n    fn hello(&self) -> String {        // по умолчанию\n        format!(\"Привет, {}!\", self.name())\n    }\n}\n```\nТип реализует только `name`, а `hello` получает бесплатно.\n\n> **Аналогия:** шаблон письма. Ты вписываешь только имя, остальной текст уже готов."},{"t":"code","code":"trait Greet {\n    fn name(&self) -> String;\n    fn hello(&self) -> String {\n        format!(\"Привет, {}!\", self.name())\n    }\n}\n\nstruct Cat;\nstruct Robot;\n\nimpl Greet for Cat {\n    fn name(&self) -> String { String::from(\"Мурка\") }\n}\n\nimpl Greet for Robot {\n    fn name(&self) -> String { String::from(\"R2\") }\n    fn hello(&self) -> String { String::from(\"БИП-БУП\") } // своё\n}\n\nfn main() {\n    println!(\"{}\", Cat.hello());\n    println!(\"{}\", Robot.hello());\n}","out":"Привет, Мурка!\nБИП-БУП","after":"`Robot` заменил метод по умолчанию своим. Так тоже можно."},{"t":"quiz","md":"Тип реализует трейт, но не пишет метод, у которого есть тело по умолчанию. Что будет?","options":["Ошибка компиляции","Тип получит готовую версию метода","Метод будет пустым"],"answer":1,"why":["Нет, для того и тело по умолчанию.","Верно.","Он будет делать то, что написано в трейте."]},{"t":"text","title":"Трейт над трейтом","md":"Иногда трейту нужен другой трейт. Например: «чтобы уметь `Report`, тип должен уметь печататься через `{}`».\n\n```\nuse std::fmt::Display;\n\ntrait Report: Display {\n    fn report(&self) -> String {\n        format!(\"[отчёт] {}\", self)\n    }\n}\n```\n`trait Report: Display` читается «Report требует Display». Такой «родительский» трейт называют **supertrait**."},{"t":"code","code":"use std::fmt;\n\ntrait Report: fmt::Display {\n    fn report(&self) -> String {\n        format!(\"[отчёт] {}\", self)\n    }\n}\n\nstruct Temp(i32);\n\nimpl fmt::Display for Temp {\n    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {\n        write!(f, \"{}°C\", self.0)\n    }\n}\n\nimpl Report for Temp {}\n\nfn main() {\n    println!(\"{}\", Temp(21).report());\n}","out":"[отчёт] 21°C","after":"`impl Report for Temp {}` — пустой: всё есть по умолчанию. Убери `impl fmt::Display` и посмотри ошибку."},{"t":"task","md":"Добавь в трейт `Shape` метод по умолчанию `describe`, который возвращает `площадь: X`, где X — результат `area()`. Квадрат реализует только `area`.","code":"trait Shape {\n    fn area(&self) -> u32;\n    // добавь describe\n}\n\nstruct Square(u32);\n\nimpl Shape for Square {\n    fn area(&self) -> u32 { self.0 * self.0 }\n}\n\nfn main() {\n    println!(\"{}\", Square(4).describe());\n}","solution":"trait Shape {\n    fn area(&self) -> u32;\n    fn describe(&self) -> String {\n        format!(\"площадь: {}\", self.area())\n    }\n}\n\nstruct Square(u32);\n\nimpl Shape for Square {\n    fn area(&self) -> u32 { self.0 * self.0 }\n}\n\nfn main() {\n    println!(\"{}\", Square(4).describe());\n}","expect":"площадь: 16","hints":["Внутри метода по умолчанию можно вызывать другие методы трейта: `self.area()`."]},{"t":"deep","title":"Правило сироты","md":"Реализовать трейт для типа можно, только если **трейт или тип твои** (объявлены в твоём крейте).\n\nНельзя написать `impl Display for Vec<i32>`: и `Display`, и `Vec` чужие. Иначе два разных крейта могли бы сделать это по-разному, и Rust не знал бы, чья версия главная.\n\nЭто называют **правилом сироты** (orphan rule). Обходят его через обёртку: `struct MyList(Vec<i32>);` — это уже твой тип, и для него можно всё."},{"t":"recap","items":["Метод с телом в трейте — метод по умолчанию. Его можно переопределить.","`trait A: B` — чтобы быть `A`, тип должен быть `B`.","Чужой трейт для чужого типа реализовать нельзя."]}],"goals":["Дать методу трейта готовую реализацию","Потребовать один трейт для другого"]},{"id":"a01-2","title":"Ассоциированные типы","min":7,"cards":[{"t":"text","title":"Тип внутри трейта","md":"Помнишь итераторы? У трейта `Iterator` есть строка:\n\n```\ntrait Iterator {\n    type Item;\n    fn next(&mut self) -> Option<Self::Item>;\n}\n```\n`type Item;` — **ассоциированный тип**. Каждый итератор сам говорит, **что** он выдаёт: числа, строки, что угодно.\n\n> **Аналогия:** автомат с едой. Трейт говорит «умею выдавать товар». Какой именно товар — решает каждый автомат: один шоколадки, другой воду."},{"t":"code","code":"trait Container {\n    type Item;\n    fn get(&self, i: usize) -> Option<&Self::Item>;\n    fn first(&self) -> Option<&Self::Item> {\n        self.get(0)\n    }\n}\n\nstruct Shelf {\n    books: Vec<String>,\n}\n\nimpl Container for Shelf {\n    type Item = String;\n    fn get(&self, i: usize) -> Option<&String> {\n        self.books.get(i)\n    }\n}\n\nfn main() {\n    let s = Shelf { books: vec![String::from(\"Дюна\"), String::from(\"Хоббит\")] };\n    println!(\"{:?}\", s.first());\n    println!(\"{:?}\", s.get(5));\n}","out":"Some(\"Дюна\")\nNone","after":"`type Item = String;` — полка выдаёт строки."},{"t":"text","title":"Почему не обобщение?","md":"Можно было бы написать `trait Container<T>`. Разница:\n- `Container<T>` — тип может реализовать его **много раз**: для `T = i32`, для `T = String`…\n- `type Item` — **ровно один раз**. У полки один вид содержимого.\n\nЕсли ответ «один тип на реализацию» — бери ассоциированный тип. Код с ним проще: не надо везде писать `<T>`."},{"t":"quiz","md":"Сколько раз один тип может реализовать трейт с ассоциированным типом `type Item`?","options":["Один раз","Сколько угодно, с разными `Item`","Ни разу, такие трейты только в стандартной библиотеке"],"answer":0,"why":["Верно. И `Item` у него один.","Так работает обобщённый трейт `Trait<T>`.","Свои тоже можно писать."]},{"t":"fill","explain":"Ассоциированный тип у `Iterator` называется `Item`, а значение возвращают в `Some(...)`.","md":"Заполни пропуски: счётчик выдаёт числа `u32`.","code":"struct Counter { n: u32 }\n\nimpl Iterator for Counter {\n    type ___ = u32;\n    fn next(&mut self) -> Option<Self::Item> {\n        if self.n < 3 {\n            self.n += 1;\n            ___(self.n)\n        } else {\n            None\n        }\n    }\n}","answers":[["Item"],["Some"]]},{"t":"recap","items":["`type Item;` в трейте — тип, который выбирает каждая реализация.","В реализации пишут `type Item = Конкретный;`.","Один тип — одна реализация — один `Item`."]}],"goals":["Понять, что такое `type Item` в трейте","Написать трейт со своим ассоциированным типом"]},{"id":"a01-3","title":"impl Trait и dyn Trait","min":8,"cards":[{"t":"text","title":"Проблема: разные типы в одном списке","md":"`Vec` хранит значения **одного** типа. А если хочется список фигур: круги, квадраты, треугольники?\n\n```\nlet shapes = vec![Circle, Square]; // ошибка: типы разные\n```\nРешение — `Box<dyn Shape>`: «коробка с чем-то, что умеет Shape»."},{"t":"code","code":"trait Shape {\n    fn area(&self) -> f64;\n    fn name(&self) -> &str;\n}\n\nstruct Circle { r: f64 }\nstruct Square { side: f64 }\n\nimpl Shape for Circle {\n    fn area(&self) -> f64 { 3.14 * self.r * self.r }\n    fn name(&self) -> &str { \"круг\" }\n}\n\nimpl Shape for Square {\n    fn area(&self) -> f64 { self.side * self.side }\n    fn name(&self) -> &str { \"квадрат\" }\n}\n\nfn main() {\n    let shapes: Vec<Box<dyn Shape>> = vec![\n        Box::new(Circle { r: 1.0 }),\n        Box::new(Square { side: 2.0 }),\n    ];\n    for s in &shapes {\n        println!(\"{}: {:.2}\", s.name(), s.area());\n    }\n}","out":"круг: 3.14\nквадрат: 4.00"},{"t":"text","title":"Два способа сказать «любой Shape»","md":"- `impl Shape` — «какой-то **один** конкретный тип, компилятор знает какой». Работает быстро: компилятор делает отдельную копию кода под каждый тип.\n- `dyn Shape` — «**любой**, узнаем во время работы». Нужен, когда типы смешаны. Чуть медленнее: метод ищется по таблице.\n\n> **Аналогия:** `impl` — заказ пиццы, где ты заранее знаешь, какая приедет. `dyn` — коробка-сюрприз: открыл и посмотрел."},{"t":"code","code":"use std::fmt::Display;\n\n// impl в аргументе: подойдёт любой тип с Display\nfn show(x: impl Display) {\n    println!(\"<{x}>\");\n}\n\n// impl в возврате: «верну итератор, не важно какой»\nfn evens(max: u32) -> impl Iterator<Item = u32> {\n    (0..=max).filter(|n| n % 2 == 0)\n}\n\nfn main() {\n    show(5);\n    show(\"кот\");\n    let v: Vec<u32> = evens(6).collect();\n    println!(\"{v:?}\");\n}","out":"<5>\n<кот>\n[0, 2, 4, 6]","after":"`impl Iterator<Item = u32>` в возврате очень частый приём: настоящий тип итератора длинный и страшный, а так его не нужно писать."},{"t":"quiz","md":"Нужен `Vec`, где лежат и `Circle`, и `Square`. Что выбрать?","options":["`Vec<impl Shape>`","`Vec<Box<dyn Shape>>`","`Vec<Shape>`"],"answer":1,"why":["`impl` означает один конкретный тип, смешать нельзя.","Верно. `dyn` позволяет хранить разные типы.","Так не скомпилируется: нужен `dyn` и коробка."]},{"t":"text","title":"Почему нужна коробка","md":"`dyn Shape` может быть кругом (8 байт) или квадратом (8 байт), а может быть чем-то на 100 байт. Размер заранее **неизвестен**, а `Vec` хочет одинаковые ячейки.\n\n`Box` решает это: в ячейке лежит только указатель (размер известен), а сама фигура — в куче. Вместо `Box` подойдёт и ссылка: `&dyn Shape`."},{"t":"deep","title":"Как работает dyn: таблица методов","md":"`Box<dyn Shape>` на самом деле хранит **два** указателя:\n1. на данные (сам круг или квадрат);\n2. на **vtable** — таблицу методов этого типа: «вот где `area`, вот где `name`».\n\nКогда ты вызываешь `s.area()`, программа смотрит в таблицу и прыгает на нужную функцию. Это называют **динамической диспетчеризацией**.\n\nС `impl` (и с обобщениями `<T: Shape>`) компилятор знает тип заранее и вызывает функцию напрямую. Это **статическая диспетчеризация**: быстрее, но код копируется под каждый тип.\n\nНе всякий трейт можно сделать `dyn`. Например, если метод возвращает `Self` или сам обобщён — таблицу не построить. Такие трейты называют не **dyn-совместимыми**."},{"t":"task","mustContain":["dyn Animal"],"md":"Сделай список животных `Vec<Box<dyn Animal>>` из кота и собаки и выведи их голоса в цикле.","code":"trait Animal {\n    fn voice(&self) -> String;\n}\n\nstruct Cat;\nstruct Dog;\n\nimpl Animal for Cat {\n    fn voice(&self) -> String { String::from(\"мяу\") }\n}\n\nimpl Animal for Dog {\n    fn voice(&self) -> String { String::from(\"гав\") }\n}\n\nfn main() {\n    // твой код\n}","solution":"trait Animal {\n    fn voice(&self) -> String;\n}\n\nstruct Cat;\nstruct Dog;\n\nimpl Animal for Cat {\n    fn voice(&self) -> String { String::from(\"мяу\") }\n}\n\nimpl Animal for Dog {\n    fn voice(&self) -> String { String::from(\"гав\") }\n}\n\nfn main() {\n    let zoo: Vec<Box<dyn Animal>> = vec![Box::new(Cat), Box::new(Dog)];\n    for a in &zoo {\n        println!(\"{}\", a.voice());\n    }\n}","expect":"мяу\nгав","hints":["Тип списка: `Vec<Box<dyn Animal>>`. Элементы: `Box::new(Cat)`, `Box::new(Dog)`."]},{"t":"recap","items":["`impl Trait` — один конкретный тип, известен компилятору. Быстро.","`dyn Trait` — любой тип, выясняется при работе. Нужен для смешанных списков.","`dyn` живёт за указателем: `Box<dyn T>` или `&dyn T`."]}],"goals":["Понять разницу между `impl Trait` и `dyn Trait`","Сложить разные типы в один `Vec`"]},{"id":"a01-4","title":"Операторы и From","min":7,"cards":[{"t":"text","title":"Операторы — тоже трейты","md":"Когда ты пишешь `a + b`, Rust вызывает метод `add` из трейта `std::ops::Add`. Реализуешь `Add` для своего типа — и `+` заработает.\n\n> **Аналогия:** знак `+` — это кнопка. Трейт `Add` — инструкция, что делать при нажатии."},{"t":"code","code":"use std::ops::Add;\n\n#[derive(Debug, Clone, Copy, PartialEq)]\nstruct Point {\n    x: i32,\n    y: i32,\n}\n\nimpl Add for Point {\n    type Output = Point;\n    fn add(self, other: Point) -> Point {\n        Point { x: self.x + other.x, y: self.y + other.y }\n    }\n}\n\nfn main() {\n    let a = Point { x: 1, y: 2 };\n    let b = Point { x: 10, y: 20 };\n    println!(\"{:?}\", a + b);\n}","out":"Point { x: 11, y: 22 }","after":"Видишь `type Output`? Это ассоциированный тип из прошлого урока: «что получится в результате сложения»."},{"t":"text","title":"Другие операторы","md":"Все они живут в `std::ops`:\n- `Sub` — `-`, `Mul` — `*`, `Div` — `/`\n- `Neg` — минус перед значением: `-a`\n- `AddAssign` — `+=`\n- `Index` — квадратные скобки: `a[i]`\n\nСравнения `==` и `<` — это `PartialEq` и `PartialOrd`. Их обычно получают через `#[derive]`."},{"t":"text","title":"From и into","md":"`From` — трейт «как сделать мой тип из другого».\n\n```\nstruct Meters(f64);\n\nimpl From<f64> for Meters {\n    fn from(x: f64) -> Self { Meters(x) }\n}\n```\nБонус: реализовал `From<A> for B` — и у `A` сам появился метод `.into()`, который превращает его в `B`."},{"t":"code","code":"struct Celsius(f64);\nstruct Fahrenheit(f64);\n\nimpl From<Celsius> for Fahrenheit {\n    fn from(c: Celsius) -> Self {\n        Fahrenheit(c.0 * 9.0 / 5.0 + 32.0)\n    }\n}\n\nfn main() {\n    let f = Fahrenheit::from(Celsius(100.0));\n    println!(\"{}\", f.0);\n    let g: Fahrenheit = Celsius(0.0).into();\n    println!(\"{}\", g.0);\n}","out":"212\n32","after":"У `into()` нужно указать, **во что** превращаем: `let g: Fahrenheit = ...`. Иначе компилятор не поймёт."},{"t":"quiz","md":"Ты реализовал `impl From<u8> for Level`. Что ещё появилось само?","options":["Ничего","Метод `.into()` у `u8`, который делает `Level`","`From<Level> for u8`"],"answer":1,"why":["Появилось кое-что полезное.","Верно. `Into` получается из `From` бесплатно.","Обратное преобразование нужно писать отдельно."]},{"t":"order","explain":"Сначала `use`, потом `impl Mul<u32> for Money`, внутри тип результата и сам метод.","md":"Собери реализацию `Mul` для `Money`, чтобы `Money(5) * 3` давало `Money(15)`.","lines":["use std::ops::Mul;","impl Mul<u32> for Money {","    type Output = Money;","    fn mul(self, k: u32) -> Money {","        Money(self.0 * k)","    }","}"]},{"t":"task","md":"Реализуй `Sub` для `Point`, чтобы `b - a` работало.","code":"use std::ops::Sub;\n\n#[derive(Debug)]\nstruct Point {\n    x: i32,\n    y: i32,\n}\n\n// твой код\n\nfn main() {\n    let a = Point { x: 1, y: 2 };\n    let b = Point { x: 10, y: 20 };\n    println!(\"{:?}\", b - a);\n}","solution":"use std::ops::Sub;\n\n#[derive(Debug)]\nstruct Point {\n    x: i32,\n    y: i32,\n}\n\nimpl Sub for Point {\n    type Output = Point;\n    fn sub(self, other: Point) -> Point {\n        Point { x: self.x - other.x, y: self.y - other.y }\n    }\n}\n\nfn main() {\n    let a = Point { x: 1, y: 2 };\n    let b = Point { x: 10, y: 20 };\n    println!(\"{:?}\", b - a);\n}","expect":"Point { x: 9, y: 18 }","hints":["Всё как с `Add`, только метод называется `sub`."]},{"t":"recap","items":["Операторы — это трейты из `std::ops`: `Add`, `Sub`, `Mul`…","`From<A> for B` — как сделать `B` из `A`. `.into()` появится сам.","У `into()` укажи тип результата."]}],"goals":["Научить свой тип складываться через `+`","Сделать преобразование типов через `From` и `into()`"]},{"id":"a01-p","title":"Практика: трейты","min":15,"cards":[{"t":"task","md":"Трейт `Priced` имеет метод `price()` в копейках и метод по умолчанию `with_tax()`, который добавляет 20%. Реализуй `Priced` для `Book` (цена 50000) и выведи обе цены.","code":"trait Priced {\n    fn price(&self) -> u32;\n    fn with_tax(&self) -> u32 {\n        // твой код\n    }\n}\n\nstruct Book;\n\n// твой код\n\nfn main() {\n    let b = Book;\n    println!(\"{}\", b.price());\n    println!(\"{}\", b.with_tax());\n}","solution":"trait Priced {\n    fn price(&self) -> u32;\n    fn with_tax(&self) -> u32 {\n        self.price() * 120 / 100\n    }\n}\n\nstruct Book;\n\nimpl Priced for Book {\n    fn price(&self) -> u32 { 50000 }\n}\n\nfn main() {\n    let b = Book;\n    println!(\"{}\", b.price());\n    println!(\"{}\", b.with_tax());\n}","expect":"50000\n60000","hints":["20% сверху — это умножить на 120 и поделить на 100."]},{"t":"task","md":"Функция `total_area` принимает срез фигур `&[Box<dyn Shape>]` и возвращает сумму площадей. Напиши её.","code":"trait Shape {\n    fn area(&self) -> u32;\n}\n\nstruct Rect { w: u32, h: u32 }\nstruct Sq(u32);\n\nimpl Shape for Rect {\n    fn area(&self) -> u32 { self.w * self.h }\n}\nimpl Shape for Sq {\n    fn area(&self) -> u32 { self.0 * self.0 }\n}\n\nfn total_area(shapes: &[Box<dyn Shape>]) -> u32 {\n    // твой код\n}\n\nfn main() {\n    let shapes: Vec<Box<dyn Shape>> = vec![\n        Box::new(Rect { w: 2, h: 3 }),\n        Box::new(Sq(4)),\n        Box::new(Sq(1)),\n    ];\n    println!(\"{}\", total_area(&shapes));\n}","solution":"trait Shape {\n    fn area(&self) -> u32;\n}\n\nstruct Rect { w: u32, h: u32 }\nstruct Sq(u32);\n\nimpl Shape for Rect {\n    fn area(&self) -> u32 { self.w * self.h }\n}\nimpl Shape for Sq {\n    fn area(&self) -> u32 { self.0 * self.0 }\n}\n\nfn total_area(shapes: &[Box<dyn Shape>]) -> u32 {\n    shapes.iter().map(|s| s.area()).sum()\n}\n\nfn main() {\n    let shapes: Vec<Box<dyn Shape>> = vec![\n        Box::new(Rect { w: 2, h: 3 }),\n        Box::new(Sq(4)),\n        Box::new(Sq(1)),\n    ];\n    println!(\"{}\", total_area(&shapes));\n}","expect":"23","hints":["`shapes.iter().map(|s| s.area()).sum()`."]},{"t":"task","md":"Сделай `impl From<&str> for Color`: `\"red\"` → `Color::Red`, `\"green\"` → `Color::Green`, всё остальное → `Color::Unknown`. Потом вызови `.into()`.","code":"#[derive(Debug)]\nenum Color {\n    Red,\n    Green,\n    Unknown,\n}\n\n// твой код\n\nfn main() {\n    let a: Color = \"red\".into();\n    let b: Color = \"green\".into();\n    let c: Color = \"purple\".into();\n    println!(\"{a:?} {b:?} {c:?}\");\n}","solution":"#[derive(Debug)]\nenum Color {\n    Red,\n    Green,\n    Unknown,\n}\n\nimpl From<&str> for Color {\n    fn from(s: &str) -> Self {\n        match s {\n            \"red\" => Color::Red,\n            \"green\" => Color::Green,\n            _ => Color::Unknown,\n        }\n    }\n}\n\nfn main() {\n    let a: Color = \"red\".into();\n    let b: Color = \"green\".into();\n    let c: Color = \"purple\".into();\n    println!(\"{a:?} {b:?} {c:?}\");\n}","expect":"Red Green Unknown","hints":["Внутри `from` сделай `match s { \"red\" => ..., \"green\" => ..., _ => ... }`."]},{"t":"task","md":"Трейт `Describe` требует `Debug` (supertrait). Метод по умолчанию `describe` возвращает `Это: ` и отладочную печать значения. Допиши трейт и реализуй его для `Pet`.","code":"use std::fmt::Debug;\n\ntrait Describe {\n    fn describe(&self) -> String {\n        format!(\"Это: {:?}\", self)\n    }\n}\n\n#[derive(Debug)]\nstruct Pet {\n    name: String,\n}\n\nfn main() {\n    let p = Pet { name: String::from(\"Бублик\") };\n    println!(\"{}\", p.describe());\n}","solution":"use std::fmt::Debug;\n\ntrait Describe: Debug {\n    fn describe(&self) -> String {\n        format!(\"Это: {:?}\", self)\n    }\n}\n\n#[derive(Debug)]\nstruct Pet {\n    name: String,\n}\n\nimpl Describe for Pet {}\n\nfn main() {\n    let p = Pet { name: String::from(\"Бублик\") };\n    println!(\"{}\", p.describe());\n}","expect":"Это: Pet { name: \"Бублик\" }","hints":["Сейчас трейт не знает, что `self` можно печатать через `{:?}`. Напиши `trait Describe: Debug`.","Реализация может быть пустой: `impl Describe for Pet {}`."]},{"t":"recap","items":["Методы по умолчанию экономят код.","`dyn` собирает разные типы в один список.","`From` делает преобразования, `.into()` приходит бонусом."]}],"practice":true,"goals":["Закрепить методы по умолчанию, `dyn` и `From`"]}]},{"id":"a02","title":"Итераторы изнутри","sub":"Свой итератор, IntoIterator, fold, collect во что угодно","lessons":[{"id":"a02-1","title":"Свой итератор","min":7,"cards":[{"t":"text","title":"Итератор — это просто next","md":"Чтобы стать итератором, типу нужно реализовать **один** метод:\n\n```\nfn next(&mut self) -> Option<Self::Item>\n```\n- Есть ещё значение — вернуть `Some(значение)`.\n- Значения кончились — вернуть `None`.\n\nВсё остальное (`map`, `filter`, `sum`, `collect`…) — методы по умолчанию. Они появятся сами.\n\n> **Аналогия:** диспенсер салфеток. Тянешь — получаешь салфетку. Пусто — ничего не выходит."},{"t":"code","code":"struct Countdown {\n    n: u32,\n}\n\nimpl Iterator for Countdown {\n    type Item = u32;\n    fn next(&mut self) -> Option<u32> {\n        if self.n == 0 {\n            None\n        } else {\n            self.n -= 1;\n            Some(self.n + 1)\n        }\n    }\n}\n\nfn main() {\n    for x in (Countdown { n: 3 }) {\n        println!(\"{x}\");\n    }\n    println!(\"старт!\");\n}","out":"3\n2\n1\nстарт!","after":"Почему `&mut self`? Итератор **помнит, где остановился**, и меняет это состояние на каждом шаге."},{"t":"code","md":"Свой итератор сразу умеет всё, что умеют обычные:","code":"struct Countdown {\n    n: u32,\n}\n\nimpl Iterator for Countdown {\n    type Item = u32;\n    fn next(&mut self) -> Option<u32> {\n        if self.n == 0 {\n            None\n        } else {\n            self.n -= 1;\n            Some(self.n + 1)\n        }\n    }\n}\n\nfn main() {\n    let total: u32 = Countdown { n: 5 }.filter(|x| x % 2 == 1).sum();\n    println!(\"{total}\");\n}","out":"9","after":"5 + 3 + 1 = 9. Мы написали только `next`, а `filter` и `sum` достались даром."},{"t":"quiz","md":"Какой метод обязательно реализовать, чтобы тип стал итератором?","options":["`iter`","`next`","`map` и `filter`"],"answer":1,"why":["Это метод коллекций, не итератора.","Верно. Всё остальное — по умолчанию.","Они уже готовы в трейте."]},{"t":"text","title":"Бесконечные итераторы","md":"`next` может **никогда** не вернуть `None`. Это нормально — просто бери нужное количество через `take`.\n\n```\nstruct Fib { a: u64, b: u64 }\n\nimpl Iterator for Fib {\n    type Item = u64;\n    fn next(&mut self) -> Option<u64> {\n        let r = self.a;\n        self.a = self.b;\n        self.b += r;\n        Some(r)\n    }\n}\n```\n`Fib { a: 0, b: 1 }.take(10)` даст первые 10 чисел Фибоначчи."},{"t":"task","md":"Допиши итератор `Fib` и выведи первые 8 чисел Фибоначчи в одну строку через `collect` в `Vec`.","code":"struct Fib {\n    a: u64,\n    b: u64,\n}\n\nimpl Iterator for Fib {\n    type Item = u64;\n    fn next(&mut self) -> Option<u64> {\n        // твой код\n    }\n}\n\nfn main() {\n    let v: Vec<u64> = Fib { a: 0, b: 1 }.take(8).collect();\n    println!(\"{v:?}\");\n}","solution":"struct Fib {\n    a: u64,\n    b: u64,\n}\n\nimpl Iterator for Fib {\n    type Item = u64;\n    fn next(&mut self) -> Option<u64> {\n        let r = self.a;\n        self.a = self.b;\n        self.b += r;\n        Some(r)\n    }\n}\n\nfn main() {\n    let v: Vec<u64> = Fib { a: 0, b: 1 }.take(8).collect();\n    println!(\"{v:?}\");\n}","expect":"[0, 1, 1, 2, 3, 5, 8, 13]","hints":["Запомни текущее `a`, потом сдвинь: `a` становится `b`, а `b` — суммой старых.","`let r = self.a; self.a = self.b; self.b += r; Some(r)`."]},{"t":"deep","title":"Где живёт состояние","md":"У каждого итератора своё состояние: счётчик, позиция в массиве, два последних числа Фибоначчи.\n\nКогда ты пишешь `v.iter().map(f).filter(g)`, получается **матрёшка** структур: `Filter<Map<Iter<i32>, F>, G>`. Каждая хранит внутреннюю и своё замыкание. Вызов `next` у внешней дёргает `next` у внутренней.\n\nКомпилятор умеет «расплющить» эту матрёшку в простой цикл. Поэтому цепочка итераторов в Rust обычно так же быстра, как цикл `for` руками. Это называют **абстракцией без накладных расходов** (zero-cost abstraction)."},{"t":"recap","items":["Итератор = `type Item` + `fn next(&mut self) -> Option<Item>`.","`None` — конец. Можно никогда не заканчивать и брать `take(n)`.","Все адаптеры (`map`, `filter`, `sum`…) приходят бесплатно."]}],"goals":["Написать тип, который умеет `next()`","Получить все методы итератора бесплатно"]},{"id":"a02-2","title":"IntoIterator: как работает for","min":7,"cards":[{"t":"text","title":"Что делает for на самом деле","md":"Строка `for x in коллекция` превращается примерно в такое:\n\n```\nlet mut it = коллекция.into_iter();\nwhile let Some(x) = it.next() {\n    // тело цикла\n}\n```\n`into_iter()` — метод трейта `IntoIterator`: «как из меня сделать итератор»."},{"t":"text","title":"Три способа обойти Vec","md":"- `for x in v.iter()` (или `for x in &v`) — `x` это `&T`. Смотрим.\n- `for x in v.iter_mut()` (или `for x in &mut v`) — `x` это `&mut T`. Меняем.\n- `for x in v` (или `v.into_iter()`) — `x` это `T`. Забираем. После цикла `v` больше нет.\n\n> **Аналогия:** коробка с конфетами. Посмотреть на каждую, переложить каждую по-другому или съесть все. После третьего коробка пустая."},{"t":"code","code":"fn main() {\n    let mut v = vec![1, 2, 3];\n    for x in &mut v {\n        *x *= 10;\n    }\n    for x in &v {\n        print!(\"{x} \");\n    }\n    println!();\n    let total: i32 = v.into_iter().sum();\n    println!(\"{total}\");\n}","out":"10 20 30\n60","after":"`*x *= 10` — звёздочка, потому что `x` здесь ссылка, а менять нужно само число."},{"t":"quiz","md":"После `for s in names { ... }` где `names: Vec<String>` — можно ли использовать `names`?","options":["Да, цикл ничего не меняет","Нет, `for` по значению забрал вектор","Да, но только `names.len()`"],"answer":1,"why":["Цикл забрал владение.","Верно. Пиши `for s in &names`, если вектор ещё нужен.","Даже это нельзя."]},{"t":"text","title":"Свой тип в for","md":"Хочешь писать `for x in &my_list`? Реализуй `IntoIterator` для `&MyList`. Проще всего — отдать итератор внутреннего вектора:\n\n```\nstruct Playlist { songs: Vec<String> }\n\nimpl<'a> IntoIterator for &'a Playlist {\n    type Item = &'a String;\n    type IntoIter = std::slice::Iter<'a, String>;\n    fn into_iter(self) -> Self::IntoIter {\n        self.songs.iter()\n    }\n}\n```\n`'a` — время жизни: элементы живут, пока жив плейлист. Подробнее — в модуле про времена жизни."},{"t":"code","code":"struct Playlist {\n    songs: Vec<String>,\n}\n\nimpl<'a> IntoIterator for &'a Playlist {\n    type Item = &'a String;\n    type IntoIter = std::slice::Iter<'a, String>;\n    fn into_iter(self) -> Self::IntoIter {\n        self.songs.iter()\n    }\n}\n\nfn main() {\n    let p = Playlist { songs: vec![String::from(\"Intro\"), String::from(\"Outro\")] };\n    for s in &p {\n        println!(\"♪ {s}\");\n    }\n    println!(\"всего: {}\", p.songs.len());\n}","out":"♪ Intro\n♪ Outro\nвсего: 2"},{"t":"fill","explain":"`iter_mut()` даёт `&mut i32`, а `*x` — само число, которое меняем.","md":"Заполни пропуски: удвой каждое число на месте, потом напечатай вектор.","code":"fn main() {\n    let mut v = vec![1, 2, 3];\n    for x in v.___() {\n        ___x *= 2;\n    }\n    println!(\"{v:?}\");\n}","answers":[["iter_mut"],["*"]]},{"t":"recap","items":["`for x in c` = `c.into_iter()` + `next()` в цикле.","`&v` → `&T`, `&mut v` → `&mut T`, `v` → `T` (вектор съеден).","Свой тип в `for` — реализуй `IntoIterator`."]}],"goals":["Понять, что `for` вызывает `into_iter()`","Различать `iter()`, `iter_mut()`, `into_iter()`"]},{"id":"a02-3","title":"Адаптеры, о которых забывают","min":8,"cards":[{"t":"text","title":"Склеить и соединить","md":"- `a.zip(b)` — идти по двум итераторам **парами**: `(a1, b1)`, `(a2, b2)`… Кончается, когда кончился короткий.\n- `a.chain(b)` — сначала весь `a`, потом весь `b`.\n- `enumerate()` — добавить номер: `(0, x)`, `(1, y)`…"},{"t":"code","code":"fn main() {\n    let names = [\"Аня\", \"Боря\", \"Вика\"];\n    let scores = [90, 75, 82];\n    for (n, s) in names.iter().zip(scores.iter()) {\n        println!(\"{n}: {s}\");\n    }\n    let all: Vec<i32> = (1..3).chain(7..9).collect();\n    println!(\"{all:?}\");\n}","out":"Аня: 90\nБоря: 75\nВика: 82\n[1, 2, 7, 8]"},{"t":"text","title":"Окна и куски (у срезов)","md":"- `v.windows(2)` — скользящее окно: `[a,b]`, `[b,c]`, `[c,d]`…\n- `v.chunks(2)` — нарезка без перекрытия: `[a,b]`, `[c,d]`, `[e]`.\n\n> **Аналогия:** `windows` — смотреть в окно поезда: каждый кадр чуть сдвинут. `chunks` — резать батон на куски."},{"t":"code","code":"fn main() {\n    let temps = [3, 5, 4, 8, 10];\n    let rises = temps.windows(2).filter(|w| w[1] > w[0]).count();\n    println!(\"потеплело {rises} раза\");\n\n    for part in [1, 2, 3, 4, 5].chunks(2) {\n        println!(\"{part:?}\");\n    }\n}","out":"потеплело 3 раза\n[1, 2]\n[3, 4]\n[5]"},{"t":"text","title":"Остановиться и пропустить","md":"- `take_while(условие)` — брать, **пока** условие правда. Первое «ложь» — стоп.\n- `skip_while(условие)` — пропускать, пока правда, потом брать всё.\n- `step_by(n)` — каждый n-й.\n- `rev()` — задом наперёд."},{"t":"text","title":"Развернуть вложенное","md":"`flat_map` — как `map`, но каждый элемент превращается в **несколько**, и всё склеивается в один поток.\n\n```\nlet words = [\"кот\", \"пёс\"];\nlet letters: Vec<char> = words.iter().flat_map(|w| w.chars()).collect();\n// ['к', 'о', 'т', 'п', 'ё', 'с']\n```\nЕсли внутри уже готовые итераторы или `Vec`, хватит `flatten()`."},{"t":"quiz","md":"Что вернёт `[1, 2, 3, 10, 4].iter().take_while(|&&x| x < 5).count()`?","options":["4","3","5"],"answer":1,"why":["`take_while` останавливается на первом неподходящем, а `4` после `10` не учитывается.","Верно. `1, 2, 3`, потом `10` — стоп.","Не все элементы меньше 5."]},{"t":"task","md":"Посчитай, сколько раз в списке два соседних числа **равны**. Используй `windows(2)`.","code":"fn main() {\n    let v = [1, 1, 2, 3, 3, 3, 4];\n    // твой код\n}","solution":"fn main() {\n    let v = [1, 1, 2, 3, 3, 3, 4];\n    let pairs = v.windows(2).filter(|w| w[0] == w[1]).count();\n    println!(\"{pairs}\");\n}","expect":"3","hints":["`v.windows(2)` даёт срезы из двух элементов: `w[0]` и `w[1]`."]},{"t":"recap","items":["`zip` — парами, `chain` — друг за другом, `enumerate` — с номером.","`windows` — скользящее окно, `chunks` — куски.","`take_while`, `skip_while`, `step_by`, `rev` — управлять потоком.","`flat_map`/`flatten` — развернуть вложенное."]}],"goals":["Познакомиться с `zip`, `chain`, `windows`, `flat_map`, `take_while`","Собирать короткие конвейеры вместо циклов"]},{"id":"a02-4","title":"fold и collect во что угодно","min":8,"cards":[{"t":"text","title":"fold — свернуть всё в одно","md":"`fold(начало, |накопленное, x| новое_накопленное)`.\n\n```\nlet sum = [1, 2, 3].iter().fold(0, |acc, x| acc + x); // 6\n```\n`sum`, `count`, `max` — это частные случаи `fold`. Когда готового метода нет — бери `fold`.\n\n> **Аналогия:** снежный ком. Катишь по снегу — каждый шаг он прилипает к себе ещё немного."},{"t":"code","code":"fn main() {\n    let words = [\"rust\", \"это\", \"весело\"];\n    let longest = words.iter().fold(\"\", |best, &w| {\n        if w.chars().count() > best.chars().count() { w } else { best }\n    });\n    println!(\"{longest}\");\n\n    let sentence = words.iter().fold(String::new(), |mut s, w| {\n        if !s.is_empty() { s.push(' '); }\n        s.push_str(w);\n        s\n    });\n    println!(\"{sentence}\");\n}","out":"весело\nrust это весело"},{"t":"text","title":"collect умеет многое","md":"`collect()` смотрит на **тип**, который ты просишь, и собирает в него:\n- `Vec<T>` — список.\n- `String` — из символов или строк.\n- `HashMap<K, V>` или `BTreeMap<K, V>` — из пар `(ключ, значение)`.\n- `Result<Vec<T>, E>` — из потока `Result`ов. Первая ошибка — и весь результат `Err`."},{"t":"code","code":"use std::collections::BTreeMap;\n\nfn main() {\n    let s: String = ['R', 'u', 's', 't'].iter().collect();\n    println!(\"{s}\");\n\n    let ages: BTreeMap<&str, u32> = [(\"Аня\", 30), (\"Боря\", 25)].into_iter().collect();\n    println!(\"{ages:?}\");\n\n    let good: Result<Vec<i32>, _> = [\"1\", \"2\", \"3\"].iter().map(|x| x.parse::<i32>()).collect();\n    println!(\"{good:?}\");\n\n    let bad: Result<Vec<i32>, _> = [\"1\", \"кот\", \"3\"].iter().map(|x| x.parse::<i32>()).collect();\n    println!(\"{}\", bad.is_err());\n}","out":"Rust\n{\"Аня\": 30, \"Боря\": 25}\nOk([1, 2, 3])\ntrue","after":"`BTreeMap` хранит ключи по порядку. Поэтому вывод всегда одинаковый — удобно для примеров."},{"t":"quiz","md":"Что получится, если собрать `[\"4\", \"x\", \"6\"]` в `Result<Vec<i32>, _>` через `parse`?","options":["`Ok([4, 6])`","`Err(...)`","`Ok([4, 0, 6])`"],"answer":1,"why":["Ошибки не выбрасываются молча.","Верно. Одна ошибка — и весь результат ошибка.","Rust не подставляет ноль сам."]},{"t":"text","title":"peekable — подсмотреть следующий","md":"Иногда нужно посмотреть на следующий элемент, **не забирая** его. Для этого `peekable()`:\n\n```\nlet mut it = [1, 2, 3].iter().peekable();\nif let Some(&&next) = it.peek() {\n    // next == 1, но он всё ещё в итераторе\n}\n```\nПригождается, когда разбираешь текст: «следующий символ цифра? тогда читаю число дальше»."},{"t":"task","md":"Посчитай, сколько раз встречается каждое слово. Собери в `BTreeMap<&str, u32>` и напечатай его.","code":"use std::collections::BTreeMap;\n\nfn main() {\n    let text = \"кот пёс кот рыба кот пёс\";\n    let mut counts: BTreeMap<&str, u32> = BTreeMap::new();\n    // твой код\n    println!(\"{counts:?}\");\n}","solution":"use std::collections::BTreeMap;\n\nfn main() {\n    let text = \"кот пёс кот рыба кот пёс\";\n    let mut counts: BTreeMap<&str, u32> = BTreeMap::new();\n    for w in text.split_whitespace() {\n        *counts.entry(w).or_insert(0) += 1;\n    }\n    println!(\"{counts:?}\");\n}","expect":"{\"кот\": 3, \"пёс\": 2, \"рыба\": 1}","hints":["`text.split_whitespace()` даёт слова.","`*counts.entry(w).or_insert(0) += 1;` — увеличить счётчик слова, создав его при первом появлении."]},{"t":"recap","items":["`fold(start, |acc, x| ...)` — свернуть в одно значение.","`collect` собирает в тот тип, который ты попросил.","`Result<Vec<_>, _>` через `collect` — остановиться на первой ошибке.","`peekable` — посмотреть следующий, не забирая."]}],"goals":["Сворачивать поток в одно значение через `fold`","Собирать в `String`, `HashMap`, `Result<Vec>`"]},{"id":"a02-p","title":"Практика: итераторы","min":15,"cards":[{"t":"task","md":"Итератор `Steps` выдаёт числа от `start` до `end` включительно с шагом `step`. Допиши `next`.","code":"struct Steps {\n    cur: u32,\n    end: u32,\n    step: u32,\n}\n\nimpl Iterator for Steps {\n    type Item = u32;\n    fn next(&mut self) -> Option<u32> {\n        // твой код\n    }\n}\n\nfn main() {\n    let v: Vec<u32> = Steps { cur: 2, end: 11, step: 3 }.collect();\n    println!(\"{v:?}\");\n}","solution":"struct Steps {\n    cur: u32,\n    end: u32,\n    step: u32,\n}\n\nimpl Iterator for Steps {\n    type Item = u32;\n    fn next(&mut self) -> Option<u32> {\n        if self.cur > self.end {\n            return None;\n        }\n        let r = self.cur;\n        self.cur += self.step;\n        Some(r)\n    }\n}\n\nfn main() {\n    let v: Vec<u32> = Steps { cur: 2, end: 11, step: 3 }.collect();\n    println!(\"{v:?}\");\n}","expect":"[2, 5, 8, 11]","hints":["Если `cur` уже больше `end` — `None`. Иначе запомни `cur`, увеличь на `step` и верни запомненное."]},{"t":"task","md":"Даны имена и баллы. Выведи только тех, у кого больше 80, в формате `имя — баллы`. Используй `zip` и `filter`.","code":"fn main() {\n    let names = [\"Аня\", \"Боря\", \"Вика\", \"Гена\"];\n    let scores = [95, 70, 88, 80];\n    // твой код\n}","solution":"fn main() {\n    let names = [\"Аня\", \"Боря\", \"Вика\", \"Гена\"];\n    let scores = [95, 70, 88, 80];\n    for (n, s) in names.iter().zip(scores.iter()).filter(|(_, s)| **s > 80) {\n        println!(\"{n} — {s}\");\n    }\n}","expect":"Аня — 95\nВика — 88","hints":["`names.iter().zip(scores.iter())` даёт пары `(&имя, &балл)`.","В `filter` приходит ссылка на пару, поэтому `**s > 80`."]},{"t":"task","md":"Преврати строку `\"3,8,x,1\"` в сумму чисел, **пропуская** то, что не число. Используй `filter_map`.","code":"fn main() {\n    let line = \"3,8,x,1\";\n    // твой код\n}","solution":"fn main() {\n    let line = \"3,8,x,1\";\n    let sum: i32 = line.split(',').filter_map(|p| p.parse::<i32>().ok()).sum();\n    println!(\"{sum}\");\n}","expect":"12","hints":["`filter_map` оставляет только `Some`. А `.ok()` превращает `Result` в `Option`."]},{"t":"task","md":"Через `fold` найди одновременно минимум и максимум списка и напечатай `мин 2, макс 9`.","code":"fn main() {\n    let v = [5, 2, 9, 4];\n    // твой код\n}","solution":"fn main() {\n    let v = [5, 2, 9, 4];\n    let (lo, hi) = v.iter().fold((i32::MAX, i32::MIN), |(lo, hi), &x| (lo.min(x), hi.max(x)));\n    println!(\"мин {lo}, макс {hi}\");\n}","expect":"мин 2, макс 9","hints":["Накопленное значение может быть парой: `(минимум, максимум)`.","Начни с `(i32::MAX, i32::MIN)`, а на каждом шаге `(lo.min(x), hi.max(x))`."]},{"t":"recap","items":["Свой итератор — только `next`.","`zip` + `filter`, `filter_map` + `ok()`, `fold` с парой — частые приёмы."]}],"practice":true,"goals":["Написать свой итератор и пару конвейеров"]}]},{"id":"a03","title":"Замыкания глубже","sub":"Fn, FnMut, FnOnce, move и функции, которые возвращают функции","lessons":[{"id":"a03-1","title":"Три вида замыканий","min":8,"cards":[{"t":"text","title":"Замыкание что-то берёт из окружения","md":"Замыкание может пользоваться переменными снаружи. **Как** оно ими пользуется — от этого зависит его вид:\n\n- `Fn` — только **смотрит**. Можно вызывать сколько угодно.\n- `FnMut` — **меняет**. Тоже можно вызывать много раз, но само замыкание должно быть `mut`.\n- `FnOnce` — **забирает** себе (съедает). Можно вызвать только один раз.\n\n> **Аналогия:** гость в доме. `Fn` — смотрит на картины. `FnMut` — переставляет мебель. `FnOnce` — уносит торт с собой. Второй раз торт не унести."},{"t":"code","code":"fn main() {\n    let name = String::from(\"Аня\");\n\n    // Fn: только читает name\n    let greet = || println!(\"Привет, {name}\");\n    greet();\n    greet();\n\n    // FnMut: меняет count\n    let mut count = 0;\n    let mut tick = || count += 1;\n    tick();\n    tick();\n    println!(\"тиков: {count}\");\n\n    // FnOnce: забирает name и отдаёт наружу\n    let take = || name;\n    let got = take();\n    println!(\"забрали: {got}\");\n}","out":"Привет, Аня\nПривет, Аня\nтиков: 2\nзабрали: Аня","after":"Попробуй вызвать `take()` второй раз. Компилятор скажет: замыкание уже «съедено»."},{"t":"text","title":"Это ещё и требования","md":"`Fn`, `FnMut`, `FnOnce` — трейты. Функция может сказать, **какое** замыкание она примет:\n\n```\nfn twice<F: Fn()>(f: F) { f(); f(); }\nfn twice_mut<F: FnMut()>(mut f: F) { f(); f(); }\nfn once<F: FnOnce()>(f: F) { f(); }\n```\n- `FnOnce` — самое мягкое требование: подойдёт **любое** замыкание.\n- `Fn` — самое строгое: подойдёт только «смотрящее»."},{"t":"quiz","md":"Замыкание `|| v.push(1)`, где `v` — вектор снаружи. Какой это вид?","options":["`Fn`","`FnMut`","`FnOnce`"],"answer":1,"why":["`push` меняет вектор, одного взгляда мало.","Верно. Оно меняет `v`.","Оно не забирает `v` себе, только меняет."]},{"t":"quiz","md":"Функция просит `F: FnOnce()`. Можно ли передать ей замыкание вида `Fn`?","options":["Да","Нет"],"answer":0,"why":["Верно. Кто умеет вызываться много раз, тот справится и один раз.","`FnOnce` — самое мягкое требование, подходит всё."]},{"t":"task","md":"Функция `apply_n` должна вызвать замыкание `n` раз. Подбери правильное требование, чтобы счётчик работал.","code":"fn apply_n<F: Fn()>(n: u32, f: F) {\n    for _ in 0..n {\n        f();\n    }\n}\n\nfn main() {\n    let mut total = 0;\n    apply_n(4, || total += 5);\n    println!(\"{total}\");\n}","solution":"fn apply_n<F: FnMut()>(n: u32, mut f: F) {\n    for _ in 0..n {\n        f();\n    }\n}\n\nfn main() {\n    let mut total = 0;\n    apply_n(4, || total += 5);\n    println!(\"{total}\");\n}","expect":"20","hints":["Замыкание меняет `total`. Значит, это `FnMut`.","Не забудь `mut f: F` — вызывать `FnMut` можно только через изменяемую переменную."]},{"t":"deep","title":"Как компилятор выбирает вид","md":"Компилятор сам смотрит, что замыкание делает с каждой захваченной переменной, и выбирает **самый мягкий** способ захвата:\n- только читает — захватит по `&`;\n- меняет — по `&mut`;\n- отдаёт наружу или передаёт кому-то по значению — заберёт себе.\n\nПолучившееся замыкание реализует сразу несколько трейтов. Каждое `Fn` — это ещё и `FnMut`, а каждое `FnMut` — ещё и `FnOnce`. Как матрёшка: `Fn` ⊂ `FnMut` ⊂ `FnOnce`.\n\nПод капотом замыкание — это безымянная структура. Её поля — захваченные переменные (или ссылки на них). А вызов — метод этой структуры."},{"t":"recap","items":["`Fn` — смотрит, `FnMut` — меняет, `FnOnce` — забирает.","Как требование: `FnOnce` подходит всем, `Fn` — самое строгое.","`FnMut` вызывают через `mut` переменную."]}],"goals":["Понять, чем отличаются `Fn`, `FnMut` и `FnOnce`","Угадывать, какой из них получится"]},{"id":"a03-2","title":"move: забрать с собой","min":6,"cards":[{"t":"text","title":"Что делает move","md":"Обычно замыкание **одалживает** переменные снаружи. `move` заставляет его **забрать** их себе (переместить внутрь).\n\n```\nlet name = String::from(\"Боря\");\nlet f = move || println!(\"{name}\");\n// name здесь больше нет: он внутри f\n```\nВажно: `move` меняет способ **захвата**, но не обязательно делает замыкание `FnOnce`. Это `f` всё ещё только читает `name`, поэтому оно `Fn`, и вызывать его можно много раз."},{"t":"text","title":"Где move нужен","md":"Когда замыкание **живёт дольше**, чем переменные вокруг него:\n- его отдают в другой поток (`thread::spawn`);\n- его возвращают из функции;\n- его кладут в структуру, которая уйдёт далеко.\n\nБез `move` замыкание держало бы ссылки на переменные, которые скоро исчезнут. Rust такого не разрешит.\n\n> **Аналогия:** уходишь из дома надолго — берёшь вещи с собой, а не записку «зонтик в шкафу»."},{"t":"code","code":"use std::thread;\n\nfn main() {\n    let data = vec![1, 2, 3];\n    let handle = thread::spawn(move || {\n        let sum: i32 = data.iter().sum();\n        println!(\"сумма в потоке: {sum}\");\n    });\n    handle.join().unwrap();\n}","out":"сумма в потоке: 6","after":"Убери `move` и запусти. Компилятор скажет, что поток может пережить `data`."},{"t":"text","title":"move и копируемые типы","md":"Если захваченная переменная `Copy` (числа, `bool`, `char`), `move` просто кладёт внутрь **копию**. Снаружи переменная остаётся.\n\n```\nlet x = 5;\nlet f = move || x + 1;\nprintln!(\"{x} {}\", f()); // 5 6 — x жив\n```"},{"t":"quiz","md":"Нужно ли `move` в `thread::spawn(|| println!(\"{v:?}\"))`, где `v` — вектор из `main`?","options":["Да","Нет, `println!` ничего не меняет","Только если `v` пустой"],"answer":0,"why":["Верно. Поток может жить дольше `main`, поэтому ему нужны свои данные.","Дело не в изменении, а во времени жизни.","Пустота вектора тут ни при чём."]},{"t":"recap","items":["`move` — забрать захваченное внутрь замыкания.","Нужен, когда замыкание переживает своё окружение: потоки, возврат из функции.","`Copy`-значения при `move` копируются."]}],"goals":["Понять, зачем писать `move` перед замыканием","Знать, где `move` обязателен"]},{"id":"a03-3","title":"Вернуть замыкание","min":7,"cards":[{"t":"text","title":"Фабрика функций","md":"Функция может **создать** и вернуть замыкание:\n\n```\nfn make_adder(n: i32) -> impl Fn(i32) -> i32 {\n    move |x| x + n\n}\n```\n`make_adder(5)` — это новая функция «прибавь 5».\n\n> **Аналогия:** штамп. Ты настраиваешь его один раз («5»), а потом штампуешь сколько угодно."},{"t":"code","code":"fn make_adder(n: i32) -> impl Fn(i32) -> i32 {\n    move |x| x + n\n}\n\nfn make_greeter(greeting: &str) -> impl Fn(&str) -> String {\n    let g = greeting.to_string();\n    move |name| format!(\"{g}, {name}!\")\n}\n\nfn main() {\n    let add5 = make_adder(5);\n    let add10 = make_adder(10);\n    println!(\"{} {}\", add5(1), add10(1));\n\n    let hi = make_greeter(\"Привет\");\n    println!(\"{}\", hi(\"Вика\"));\n}","out":"6 11\nПривет, Вика!","after":"`move` тут обязателен: `n` и `g` умрут, когда функция закончится, а замыкание продолжит жить."},{"t":"text","title":"Когда нужен Box<dyn Fn>","md":"`impl Fn` значит «один конкретный тип». А если функция возвращает **разные** замыкания в разных ветках?\n\n```\nfn op(name: &str) -> Box<dyn Fn(i32, i32) -> i32> {\n    match name {\n        \"+\" => Box::new(|a, b| a + b),\n        \"*\" => Box::new(|a, b| a * b),\n        _ => Box::new(|_, _| 0),\n    }\n}\n```\nУ каждого замыкания свой тип, даже если они выглядят одинаково. Поэтому — коробка с `dyn`, как в модуле про трейты."},{"t":"code","code":"fn op(name: &str) -> Box<dyn Fn(i32, i32) -> i32> {\n    match name {\n        \"+\" => Box::new(|a, b| a + b),\n        \"*\" => Box::new(|a, b| a * b),\n        _ => Box::new(|_, _| 0),\n    }\n}\n\nfn main() {\n    for name in [\"+\", \"*\", \"?\"] {\n        let f = op(name);\n        println!(\"6 {name} 7 = {}\", f(6, 7));\n    }\n}","out":"6 + 7 = 13\n6 * 7 = 42\n6 ? 7 = 0"},{"t":"quiz","md":"Функция в одной ветке `if` возвращает `|x| x + 1`, а в другой `|x| x * 2`. Что писать в типе результата?","options":["`impl Fn(i32) -> i32`","`Box<dyn Fn(i32) -> i32>`","`Fn(i32) -> i32`"],"answer":1,"why":["Это два разных типа, `impl` их не объединит.","Верно.","Без `impl` или `dyn` так писать нельзя."]},{"t":"text","title":"Обычные функции тоже подходят","md":"Тип `fn(i32) -> i32` (с маленькой `f`) — **указатель на функцию**. Это обычная функция или замыкание, которое ничего не захватывает.\n\n```\nfn double(x: i32) -> i32 { x * 2 }\nlet f: fn(i32) -> i32 = double;\nlet v: Vec<i32> = [1, 2].iter().map(|&x| f(x)).collect();\n```\nОбычную функцию можно передать везде, где ждут `Fn`: `.map(double)` тоже работает."},{"t":"task","md":"Напиши `make_multiplier(k)`, которая возвращает замыкание «умножь на k».","code":"fn make_multiplier(k: i32) -> impl Fn(i32) -> i32 {\n    // твой код\n}\n\nfn main() {\n    let triple = make_multiplier(3);\n    println!(\"{}\", triple(7));\n    let v: Vec<i32> = vec![1, 2, 3].into_iter().map(make_multiplier(10)).collect();\n    println!(\"{v:?}\");\n}","solution":"fn make_multiplier(k: i32) -> impl Fn(i32) -> i32 {\n    move |x| x * k\n}\n\nfn main() {\n    let triple = make_multiplier(3);\n    println!(\"{}\", triple(7));\n    let v: Vec<i32> = vec![1, 2, 3].into_iter().map(make_multiplier(10)).collect();\n    println!(\"{v:?}\");\n}","expect":"21\n[10, 20, 30]","hints":["Тело — одна строка: `move |x| x * k`."]},{"t":"recap","items":["`-> impl Fn(A) -> B` — вернуть одно замыкание. Почти всегда с `move`.","Разные замыкания в разных ветках — `Box<dyn Fn(A) -> B>`.","`fn(A) -> B` — указатель на обычную функцию."]}],"goals":["Написать функцию, которая возвращает функцию","Выбирать между `impl Fn` и `Box<dyn Fn>`"]},{"id":"a03-4","title":"Замыкания в структурах","min":7,"cards":[{"t":"text","title":"Поле-функция","md":"Замыкание можно положить в структуру. Два способа:\n\n```\nstruct Button<F: Fn()> {\n    on_click: F,                 // один конкретный тип, быстро\n}\n\nstruct Menu {\n    actions: Vec<Box<dyn Fn()>>, // много разных замыканий\n}\n```\nВторой способ нужен, когда обработчиков много и они разные."},{"t":"code","code":"struct EventBus {\n    handlers: Vec<Box<dyn Fn(&str)>>,\n}\n\nimpl EventBus {\n    fn new() -> Self {\n        EventBus { handlers: Vec::new() }\n    }\n    fn subscribe(&mut self, f: impl Fn(&str) + 'static) {\n        self.handlers.push(Box::new(f));\n    }\n    fn emit(&self, event: &str) {\n        for h in &self.handlers {\n            h(event);\n        }\n    }\n}\n\nfn main() {\n    let mut bus = EventBus::new();\n    bus.subscribe(|e| println!(\"лог: {e}\"));\n    let prefix = String::from(\">>\");\n    bus.subscribe(move |e| println!(\"{prefix} {}\", e.to_uppercase()));\n    bus.emit(\"save\");\n}","out":"лог: save\n>> SAVE","after":"`+ 'static` значит: «замыкание не держит ссылок на временные вещи». Поэтому для `prefix` нужен `move`."},{"t":"text","title":"Вызвать поле","md":"Если замыкание лежит в поле, вызов пишут в скобках:\n\n```\n(self.on_click)();\n```\nБез скобок `self.on_click()` Rust будет искать **метод** `on_click`, а не поле."},{"t":"fill","explain":"`(self.on_click)()` — сначала достать поле, потом вызвать его.","md":"Заполни пропуски, чтобы кнопка вызвала свой обработчик.","code":"struct Button<F: Fn()> {\n    on_click: F,\n}\n\nimpl<F: Fn()> Button<F> {\n    fn press(&self) {\n        ___self.on_click___();\n    }\n}","answers":[["("],[")"]]},{"t":"task","md":"Сделай `Counter`, который хранит шаг как замыкание `Box<dyn Fn(i32) -> i32>` и применяет его в методе `next`. Начни с 1, шаг — умножить на 3. Напечатай три значения.","code":"struct Counter {\n    value: i32,\n    step: Box<dyn Fn(i32) -> i32>,\n}\n\nimpl Counter {\n    fn next(&mut self) -> i32 {\n        // твой код\n    }\n}\n\nfn main() {\n    let mut c = Counter { value: 1, step: Box::new(|x| x * 3) };\n    println!(\"{}\", c.next());\n    println!(\"{}\", c.next());\n    println!(\"{}\", c.next());\n}","solution":"struct Counter {\n    value: i32,\n    step: Box<dyn Fn(i32) -> i32>,\n}\n\nimpl Counter {\n    fn next(&mut self) -> i32 {\n        self.value = (self.step)(self.value);\n        self.value\n    }\n}\n\nfn main() {\n    let mut c = Counter { value: 1, step: Box::new(|x| x * 3) };\n    println!(\"{}\", c.next());\n    println!(\"{}\", c.next());\n    println!(\"{}\", c.next());\n}","expect":"3\n9\n27","hints":["Вызов поля — в скобках: `(self.step)(self.value)`."]},{"t":"recap","items":["Замыкание в поле: `F: Fn()` (один тип) или `Box<dyn Fn()>` (разные).","Вызывать поле: `(self.f)(аргументы)`.","`+ 'static` — замыкание не держит временных ссылок."]}],"goals":["Хранить замыкание в поле структуры","Сделать простую систему обработчиков событий"]},{"id":"a03-p","title":"Практика: замыкания","min":14,"cards":[{"t":"task","md":"Функция `compose(f, g)` возвращает новую функцию «сначала `f`, потом `g`». Допиши её.","code":"fn compose(f: impl Fn(i32) -> i32, g: impl Fn(i32) -> i32) -> impl Fn(i32) -> i32 {\n    // твой код\n}\n\nfn main() {\n    let inc_then_double = compose(|x| x + 1, |x| x * 2);\n    println!(\"{}\", inc_then_double(5));\n}","solution":"fn compose(f: impl Fn(i32) -> i32, g: impl Fn(i32) -> i32) -> impl Fn(i32) -> i32 {\n    move |x| g(f(x))\n}\n\nfn main() {\n    let inc_then_double = compose(|x| x + 1, |x| x * 2);\n    println!(\"{}\", inc_then_double(5));\n}","expect":"12","hints":["Новое замыкание забирает `f` и `g` себе: `move |x| ...`.","Сначала `f(x)`, потом результат в `g`: `g(f(x))`."]},{"t":"task","md":"Функция `run_once` принимает `FnOnce() -> String` и печатает результат. Передай ей замыкание, которое **отдаёт** строку `report` наружу.","code":"fn run_once<F: FnOnce() -> String>(f: F) {\n    println!(\"{}\", f());\n}\n\nfn main() {\n    let report = String::from(\"отчёт готов\");\n    // твой код\n}","solution":"fn run_once<F: FnOnce() -> String>(f: F) {\n    println!(\"{}\", f());\n}\n\nfn main() {\n    let report = String::from(\"отчёт готов\");\n    run_once(move || report);\n}","expect":"отчёт готов","hints":["Замыкание просто возвращает `report`: `|| report`. `move` можно добавить для ясности."]},{"t":"task","md":"Собери «калькулятор»: `Vec<(&str, Box<dyn Fn(i32, i32) -> i32>)>` с операциями `+`, `-`, `max`. Примени каждую к числам 8 и 3 и выведи `имя: результат`.","code":"fn main() {\n    let a = 8;\n    let b = 3;\n    // твой код\n}","solution":"fn main() {\n    let a = 8;\n    let b = 3;\n    let ops: Vec<(&str, Box<dyn Fn(i32, i32) -> i32>)> = vec![\n        (\"+\", Box::new(|x, y| x + y)),\n        (\"-\", Box::new(|x, y| x - y)),\n        (\"max\", Box::new(|x: i32, y| x.max(y))),\n    ];\n    for (name, f) in &ops {\n        println!(\"{name}: {}\", f(a, b));\n    }\n}","expect":"+: 11\n-: 5\nmax: 8","hints":["Каждый элемент — пара `(\"имя\", Box::new(|x, y| ...))`.","Для `max` компилятору может понадобиться тип: `|x: i32, y| x.max(y)`."]},{"t":"task","md":"Функция `memo_square` возвращает замыкание `FnMut(u64)`, которое считает квадрат и **считает свои вызовы**. Напечатай результат и число вызовов после трёх вызовов.","code":"fn memo_square() -> impl FnMut(u64) -> (u64, u32) {\n    // твой код\n}\n\nfn main() {\n    let mut sq = memo_square();\n    sq(2);\n    sq(3);\n    let (v, calls) = sq(4);\n    println!(\"{v} {calls}\");\n}","solution":"fn memo_square() -> impl FnMut(u64) -> (u64, u32) {\n    let mut calls = 0;\n    move |x| {\n        calls += 1;\n        (x * x, calls)\n    }\n}\n\nfn main() {\n    let mut sq = memo_square();\n    sq(2);\n    sq(3);\n    let (v, calls) = sq(4);\n    println!(\"{v} {calls}\");\n}","expect":"16 3","hints":["Заведи `let mut calls = 0;` и верни `move |x| { calls += 1; (x * x, calls) }`."]},{"t":"recap","items":["Комбинировать функции — вернуть `move |x| g(f(x))`.","Замыкание со своим состоянием — `FnMut` + `move`.","Список разных операций — `Vec<Box<dyn Fn(...)>>`."]}],"practice":true,"goals":["Применить все три вида замыканий и вернуть замыкание из функции"]}]},{"id":"a04","title":"Ошибки в больших программах","sub":"Свои типы ошибок, From и ?, Box<dyn Error>, anyhow и thiserror","lessons":[{"id":"a04-1","title":"Свой тип ошибки","min":8,"cards":[{"t":"text","title":"Почему String плохо для ошибок","md":"В основах мы часто писали `Result<T, String>`. Это просто, но:\n- по строке трудно понять, **какая** именно ошибка, и по-разному на неё ответить;\n- легко опечататься в тексте.\n\nВ больших программах ошибки описывают через `enum`. Каждый вариант — один вид проблемы.\n\n> **Аналогия:** врач не пишет в карте «что-то болит». Он пишет диагноз из списка. По диагнозу понятно, как лечить."},{"t":"code","code":"#[derive(Debug)]\nenum LoginError {\n    EmptyName,\n    TooShort(usize),\n    Banned { name: String },\n}\n\nfn check(name: &str) -> Result<(), LoginError> {\n    if name.is_empty() {\n        return Err(LoginError::EmptyName);\n    }\n    if name.len() < 3 {\n        return Err(LoginError::TooShort(name.len()));\n    }\n    if name == \"admin\" {\n        return Err(LoginError::Banned { name: name.to_string() });\n    }\n    Ok(())\n}\n\nfn main() {\n    for n in [\"\", \"ab\", \"admin\", \"alice\"] {\n        println!(\"{:?}\", check(n));\n    }\n}","out":"Err(EmptyName)\nErr(TooShort(2))\nErr(Banned { name: \"admin\" })\nOk(())","after":"В вариантах можно хранить подробности: длину, имя — что угодно."},{"t":"text","title":"Понятный текст: Display","md":"`{:?}` — для программиста. Для человека нужен `{}`. Его даёт трейт `Display`:\n\n```\nuse std::fmt;\n\nimpl fmt::Display for LoginError {\n    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {\n        match self {\n            LoginError::EmptyName => write!(f, \"имя пустое\"),\n            LoginError::TooShort(n) => write!(f, \"имя короткое: {n} симв.\"),\n            LoginError::Banned { name } => write!(f, \"{name} заблокирован\"),\n        }\n    }\n}\n```"},{"t":"text","title":"Трейт Error","md":"В стандартной библиотеке есть трейт `std::error::Error`. Он говорит: «я — ошибка». Требует `Debug` и `Display`, а сам может быть пустым:\n\n```\nimpl std::error::Error for LoginError {}\n```\nЗачем? Тогда твою ошибку можно положить в `Box<dyn Error>`, отдать чужому коду и вообще обращаться с ней, как с любой ошибкой Rust."},{"t":"quiz","md":"Какие трейты нужны, чтобы реализовать `std::error::Error`?","options":["Только `Clone`","`Debug` и `Display`","`From` и `Into`"],"answer":1,"why":["`Clone` ошибкам не обязателен.","Верно. Это его супертрейты.","Они полезны, но не обязательны."]},{"t":"task","md":"Допиши `Display` для `ParseColorError`, чтобы программа печатала понятные сообщения.","code":"use std::fmt;\n\n#[derive(Debug)]\nenum ParseColorError {\n    Empty,\n    Unknown(String),\n}\n\nimpl fmt::Display for ParseColorError {\n    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {\n        // твой код\n    }\n}\n\nimpl std::error::Error for ParseColorError {}\n\nfn parse(s: &str) -> Result<&str, ParseColorError> {\n    match s {\n        \"\" => Err(ParseColorError::Empty),\n        \"red\" | \"green\" => Ok(s),\n        other => Err(ParseColorError::Unknown(other.to_string())),\n    }\n}\n\nfn main() {\n    for s in [\"red\", \"\", \"pink\"] {\n        match parse(s) {\n            Ok(c) => println!(\"цвет: {c}\"),\n            Err(e) => println!(\"ошибка: {e}\"),\n        }\n    }\n}","solution":"use std::fmt;\n\n#[derive(Debug)]\nenum ParseColorError {\n    Empty,\n    Unknown(String),\n}\n\nimpl fmt::Display for ParseColorError {\n    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {\n        match self {\n            ParseColorError::Empty => write!(f, \"пустая строка\"),\n            ParseColorError::Unknown(s) => write!(f, \"неизвестный цвет «{s}»\"),\n        }\n    }\n}\n\nimpl std::error::Error for ParseColorError {}\n\nfn parse(s: &str) -> Result<&str, ParseColorError> {\n    match s {\n        \"\" => Err(ParseColorError::Empty),\n        \"red\" | \"green\" => Ok(s),\n        other => Err(ParseColorError::Unknown(other.to_string())),\n    }\n}\n\nfn main() {\n    for s in [\"red\", \"\", \"pink\"] {\n        match parse(s) {\n            Ok(c) => println!(\"цвет: {c}\"),\n            Err(e) => println!(\"ошибка: {e}\"),\n        }\n    }\n}","expect":"цвет: red\nошибка: пустая строка\nошибка: неизвестный цвет «pink»","hints":["Внутри `fmt` сделай `match self { ... }` и в каждой ветке `write!(f, \"...\")`."]},{"t":"recap","items":["Ошибки большой программы — `enum`, по варианту на каждый вид.","`Display` — текст для людей, `Debug` — для программистов.","`impl std::error::Error for MyError {}` — «я настоящая ошибка»."]}],"goals":["Описать все ошибки программы одним `enum`","Научить ошибку печататься понятно"]},{"id":"a04-2","title":"From и ?: ошибки сами превращаются","min":8,"cards":[{"t":"text","title":"Проблема: ошибки разных видов","md":"Функция читает число из текста и проверяет его. Может сломаться `parse` (ошибка `ParseIntError`), а может твоя проверка (`AppError`). Но вернуть функция может только **один** тип ошибки."},{"t":"text","title":"Секрет ?","md":"`?` делает чуть больше, чем кажется. При ошибке он вызывает `From::from(ошибка)` — **превращает** её в тип ошибки функции.\n\nЗначит, достаточно написать `impl From<ParseIntError> for AppError` — и `?` будет сам переводить одну ошибку в другую.\n\n> **Аналогия:** переходник для розетки. Вилка чужая, розетка твоя — переходник (`From`) их соединяет."},{"t":"code","code":"use std::fmt;\nuse std::num::ParseIntError;\n\n#[derive(Debug)]\nenum AppError {\n    NotNumber(ParseIntError),\n    Negative(i32),\n}\n\nimpl fmt::Display for AppError {\n    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {\n        match self {\n            AppError::NotNumber(e) => write!(f, \"не число: {e}\"),\n            AppError::Negative(n) => write!(f, \"отрицательное: {n}\"),\n        }\n    }\n}\n\nimpl From<ParseIntError> for AppError {\n    fn from(e: ParseIntError) -> Self {\n        AppError::NotNumber(e)\n    }\n}\n\nfn read_positive(s: &str) -> Result<i32, AppError> {\n    let n: i32 = s.trim().parse()?; // ParseIntError -> AppError сам\n    if n < 0 {\n        return Err(AppError::Negative(n));\n    }\n    Ok(n)\n}\n\nfn main() {\n    for s in [\"42\", \"-5\", \"кот\"] {\n        match read_positive(s) {\n            Ok(n) => println!(\"ok {n}\"),\n            Err(e) => println!(\"ошибка: {e}\"),\n        }\n    }\n}","out":"ok 42\nошибка: отрицательное: -5\nошибка: не число: invalid digit found in string","after":"Убери `impl From` — и `?` перестанет компилироваться: Rust не знает, как превратить одно в другое."},{"t":"quiz","md":"Что делает `?`, когда функция возвращает `Result<T, AppError>`, а вызов вернул `Err(ParseIntError)`?","options":["Паникует","Не компилируется никогда","Вызывает `AppError::from(...)` и возвращает результат"],"answer":2,"why":["Нет, паники тут нет.","Скомпилируется, если есть подходящий `From`.","Верно."]},{"t":"fill","explain":"Нужен `impl From<std::io::Error> for MyError` с методом `from`.","md":"Заполни пропуски, чтобы `?` мог превратить `std::io::Error` в `MyError`.","code":"impl ___<std::io::Error> for MyError {\n    fn ___(e: std::io::Error) -> Self {\n        MyError::Io(e)\n    }\n}","answers":[["From"],["from"]]},{"t":"text","title":"map_err: превратить руками","md":"Иногда `From` писать не хочется — ошибка нужна в одном месте. Тогда `map_err`:\n\n```\nlet n: i32 = s.parse().map_err(|_| AppError::Negative(0))?;\n```\n`map_err` меняет ошибку, а `?` уже возвращает готовую."},{"t":"task","md":"Сделай `impl From<ParseIntError> for AgeError`, чтобы `?` в `parse_age` заработал.","code":"use std::num::ParseIntError;\n\n#[derive(Debug)]\nenum AgeError {\n    Bad(ParseIntError),\n    TooOld(u32),\n}\n\n// твой код\n\nfn parse_age(s: &str) -> Result<u32, AgeError> {\n    let n: u32 = s.parse()?;\n    if n > 150 {\n        return Err(AgeError::TooOld(n));\n    }\n    Ok(n)\n}\n\nfn main() {\n    println!(\"{:?}\", parse_age(\"30\"));\n    println!(\"{:?}\", parse_age(\"200\"));\n    println!(\"{}\", matches!(parse_age(\"x\"), Err(AgeError::Bad(_))));\n}","solution":"use std::num::ParseIntError;\n\n#[derive(Debug)]\nenum AgeError {\n    Bad(ParseIntError),\n    TooOld(u32),\n}\n\nimpl From<ParseIntError> for AgeError {\n    fn from(e: ParseIntError) -> Self {\n        AgeError::Bad(e)\n    }\n}\n\nfn parse_age(s: &str) -> Result<u32, AgeError> {\n    let n: u32 = s.parse()?;\n    if n > 150 {\n        return Err(AgeError::TooOld(n));\n    }\n    Ok(n)\n}\n\nfn main() {\n    println!(\"{:?}\", parse_age(\"30\"));\n    println!(\"{:?}\", parse_age(\"200\"));\n    println!(\"{}\", matches!(parse_age(\"x\"), Err(AgeError::Bad(_))));\n}","expect":"Ok(30)\nErr(TooOld(200))\ntrue","hints":["`impl From<ParseIntError> for AgeError { fn from(e: ParseIntError) -> Self { ... } }`."]},{"t":"recap","items":["`?` вызывает `From::from` для ошибки.","`impl From<ЧужаяОшибка> for МояОшибка` — и `?` сам переводит.","Разово — `map_err(|e| ...)?`."]}],"goals":["Понять, что `?` умеет менять тип ошибки","Собрать ошибки из разных мест в одну"]},{"id":"a04-3","title":"Box<dyn Error>: любая ошибка","min":7,"cards":[{"t":"text","title":"Ленивый, но честный вариант","md":"Иногда свой `enum` — это слишком. Например, в маленьком скрипте или в `main`. Тогда пишут:\n\n```\nfn run() -> Result<(), Box<dyn std::error::Error>> { ... }\n```\n`Box<dyn Error>` — «коробка с **какой-то** ошибкой». Любой тип с трейтом `Error` превращается в неё через `?` сам.\n\n> **Аналогия:** общая корзина для всех жалоб. Удобно складывать, но разбирать потом сложнее."},{"t":"code","code":"use std::error::Error;\n\nfn sum_line(line: &str) -> Result<i32, Box<dyn Error>> {\n    let mut total = 0;\n    for part in line.split('+') {\n        let n: i32 = part.trim().parse()?;\n        total += n;\n    }\n    if total > 100 {\n        return Err(\"слишком много\".into());\n    }\n    Ok(total)\n}\n\nfn main() {\n    println!(\"{:?}\", sum_line(\"1 + 2 + 3\").ok());\n    match sum_line(\"1 + x\") {\n        Err(e) => println!(\"ошибка: {e}\"),\n        Ok(_) => {}\n    }\n    match sum_line(\"60 + 70\") {\n        Err(e) => println!(\"ошибка: {e}\"),\n        Ok(_) => {}\n    }\n}","out":"Some(6)\nошибка: invalid digit found in string\nошибка: слишком много","after":"`\"слишком много\".into()` — даже обычную строку можно превратить в `Box<dyn Error>`."},{"t":"text","title":"Когда что выбирать","md":"- **Библиотека**, которую будут использовать другие — свой `enum`. Пусть пользователь сможет сделать `match` по вариантам.\n- **Приложение** или скрипт, где ошибку в основном печатают — `Box<dyn Error>` (или крейт `anyhow`, о нём в следующем уроке)."},{"t":"text","title":"main тоже может вернуть Result","md":"```\nfn main() -> Result<(), Box<dyn std::error::Error>> {\n    let n: i32 = \"42\".parse()?;\n    println!(\"{n}\");\n    Ok(())\n}\n```\nЕсли `main` вернёт `Err`, программа напечатает `Error: ...` и завершится с кодом ошибки. Удобно для коротких программ."},{"t":"quiz","md":"Ты пишешь библиотеку для чтения настроек. Её будут подключать другие программы. Что выбрать для ошибок?","options":["Свой `enum` ошибок","`Box<dyn Error>`","`String`"],"answer":0,"why":["Верно. Пользователь сможет различать случаи.","Пользователь не сможет удобно понять, что именно случилось.","Так ещё хуже: только текст."]},{"t":"deep","title":"Цепочка причин: source()","md":"Хорошая ошибка помнит, **из-за чего** она случилась. Для этого у трейта `Error` есть метод `source()`:\n\n```\nimpl std::error::Error for ConfigError {\n    fn source(&self) -> Option<&(dyn std::error::Error + 'static)> {\n        match self {\n            ConfigError::BadPort(e) => Some(e), // внутри ParseIntError\n            _ => None,\n        }\n    }\n}\n```\nТак получается цепочка: «не прочитал настройки» → «порт неверный» → «в строке не цифра». Логгеры и `anyhow` умеют печатать её целиком. Это очень помогает искать причину проблемы."},{"t":"recap","items":["`Box<dyn Error>` — любая ошибка, `?` складывает туда всё сам.","Библиотеке — свой `enum`, приложению — `Box<dyn Error>` или `anyhow`.","`main` может вернуть `Result`."]}],"goals":["Возвращать «любую ошибку» без своего `enum`","Узнать про цепочку причин `source()`"]},{"id":"a04-4","title":"thiserror и anyhow","min":7,"cards":[{"t":"text","title":"Два популярных помощника","md":"Мы писали `Display` и `From` руками. Это много одинакового кода. Два крейта делают это за тебя:\n- **thiserror** — для **своих** типов ошибок. Пишешь `enum`, а `Display`, `Error` и `From` генерируются атрибутами.\n- **anyhow** — для **приложений**. Это удобный `Box<dyn Error>` с добавлением контекста.\n\nВ своём проекте их подключают в `Cargo.toml`. В Playground они уже есть."},{"t":"code","crates":true,"md":"thiserror: текст ошибки прямо над вариантом, `#[from]` — и `From` готов.","code":"use thiserror::Error;\n\n#[derive(Debug, Error)]\nenum AppError {\n    #[error(\"не число: {0}\")]\n    NotNumber(#[from] std::num::ParseIntError),\n    #[error(\"отрицательное: {0}\")]\n    Negative(i32),\n}\n\nfn read_positive(s: &str) -> Result<i32, AppError> {\n    let n: i32 = s.parse()?;\n    if n < 0 {\n        return Err(AppError::Negative(n));\n    }\n    Ok(n)\n}\n\nfn main() {\n    for s in [\"7\", \"-1\", \"x\"] {\n        match read_positive(s) {\n            Ok(n) => println!(\"ok {n}\"),\n            Err(e) => println!(\"ошибка: {e}\"),\n        }\n    }\n}","out":"ok 7\nошибка: отрицательное: -1\nошибка: не число: invalid digit found in string","after":"Сравни с прошлым уроком: тот же результат, но втрое меньше кода."},{"t":"code","crates":true,"md":"anyhow: любая ошибка + понятный контекст.","code":"use anyhow::{Context, Result, bail};\n\nfn parse_port(s: &str) -> Result<u16> {\n    let port: u16 = s.parse().context(\"порт должен быть числом\")?;\n    if port < 1024 {\n        bail!(\"порт {port} зарезервирован\");\n    }\n    Ok(port)\n}\n\nfn main() {\n    for s in [\"8080\", \"80\", \"http\"] {\n        match parse_port(s) {\n            Ok(p) => println!(\"порт {p}\"),\n            Err(e) => println!(\"ошибка: {e:#}\"),\n        }\n    }\n}","out":"порт 8080\nошибка: порт 80 зарезервирован\nошибка: порт должен быть числом: invalid digit found in string","after":"- `.context(\"...\")` — добавить пояснение сверху.\n- `bail!(...)` — сразу вернуть ошибку с текстом.\n- `{e:#}` — напечатать всю цепочку причин через двоеточие."},{"t":"quiz","md":"Ты пишешь консольную утилиту для себя. Ошибки нужно просто понятно напечатать. Что удобнее?","options":["thiserror","anyhow","Свой `enum` руками"],"answer":1,"why":["Он хорош, когда кто-то будет разбирать варианты ошибок.","Верно. Минимум кода и понятный контекст.","Можно, но долго и без пользы."]},{"t":"text","title":"Правило на каждый день","md":"- Пишешь **библиотеку** → `thiserror`.\n- Пишешь **программу** → `anyhow`.\n- Часто их используют вместе: библиотека отдаёт `thiserror`-ошибки, а приложение заворачивает их в `anyhow` с контекстом."},{"t":"recap","items":["`thiserror`: `#[derive(Error)]`, `#[error(\"...\")]`, `#[from]`.","`anyhow`: `Result<T>`, `.context(...)`, `bail!`.","Библиотека — thiserror, приложение — anyhow."]}],"goals":["Убрать шаблонный код ошибок с помощью крейтов","Понять, какой крейт для чего"]},{"id":"a04-p","title":"Практика: ошибки","min":15,"cards":[{"t":"task","md":"Функция `withdraw` снимает деньги со счёта. Ошибки: `NotEnough { need, have }` и `Zero`. Допиши `Display`, чтобы вывод совпал.","code":"use std::fmt;\n\n#[derive(Debug)]\nenum BankError {\n    Zero,\n    NotEnough { need: u32, have: u32 },\n}\n\nimpl fmt::Display for BankError {\n    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {\n        // твой код\n    }\n}\n\nfn withdraw(balance: &mut u32, amount: u32) -> Result<(), BankError> {\n    if amount == 0 {\n        return Err(BankError::Zero);\n    }\n    if amount > *balance {\n        return Err(BankError::NotEnough { need: amount, have: *balance });\n    }\n    *balance -= amount;\n    Ok(())\n}\n\nfn main() {\n    let mut b = 100;\n    for a in [30, 0, 500] {\n        match withdraw(&mut b, a) {\n            Ok(()) => println!(\"сняли {a}, осталось {b}\"),\n            Err(e) => println!(\"ошибка: {e}\"),\n        }\n    }\n}","solution":"use std::fmt;\n\n#[derive(Debug)]\nenum BankError {\n    Zero,\n    NotEnough { need: u32, have: u32 },\n}\n\nimpl fmt::Display for BankError {\n    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {\n        match self {\n            BankError::Zero => write!(f, \"сумма равна нулю\"),\n            BankError::NotEnough { need, have } => write!(f, \"нужно {need}, есть {have}\"),\n        }\n    }\n}\n\nfn withdraw(balance: &mut u32, amount: u32) -> Result<(), BankError> {\n    if amount == 0 {\n        return Err(BankError::Zero);\n    }\n    if amount > *balance {\n        return Err(BankError::NotEnough { need: amount, have: *balance });\n    }\n    *balance -= amount;\n    Ok(())\n}\n\nfn main() {\n    let mut b = 100;\n    for a in [30, 0, 500] {\n        match withdraw(&mut b, a) {\n            Ok(()) => println!(\"сняли {a}, осталось {b}\"),\n            Err(e) => println!(\"ошибка: {e}\"),\n        }\n    }\n}","expect":"сняли 30, осталось 70\nошибка: сумма равна нулю\nошибка: нужно 500, есть 70","hints":["Вариант с полями разбирают так: `BankError::NotEnough { need, have } => write!(f, \"нужно {need}, есть {have}\")`."]},{"t":"task","md":"Функция `parse_point` разбирает строку `\"3,4\"` в пару чисел. Ошибки: `NoComma` и `Num(ParseIntError)`. Сделай `From`, чтобы работал `?`.","code":"use std::num::ParseIntError;\n\n#[derive(Debug)]\nenum PointError {\n    NoComma,\n    Num(ParseIntError),\n}\n\n// твой код\n\nfn parse_point(s: &str) -> Result<(i32, i32), PointError> {\n    let (a, b) = s.split_once(',').ok_or(PointError::NoComma)?;\n    Ok((a.trim().parse()?, b.trim().parse()?))\n}\n\nfn main() {\n    println!(\"{:?}\", parse_point(\"3, 4\"));\n    println!(\"{:?}\", parse_point(\"3 4\"));\n    println!(\"{}\", matches!(parse_point(\"3,x\"), Err(PointError::Num(_))));\n}","solution":"use std::num::ParseIntError;\n\n#[derive(Debug)]\nenum PointError {\n    NoComma,\n    Num(ParseIntError),\n}\n\nimpl From<ParseIntError> for PointError {\n    fn from(e: ParseIntError) -> Self {\n        PointError::Num(e)\n    }\n}\n\nfn parse_point(s: &str) -> Result<(i32, i32), PointError> {\n    let (a, b) = s.split_once(',').ok_or(PointError::NoComma)?;\n    Ok((a.trim().parse()?, b.trim().parse()?))\n}\n\nfn main() {\n    println!(\"{:?}\", parse_point(\"3, 4\"));\n    println!(\"{:?}\", parse_point(\"3 4\"));\n    println!(\"{}\", matches!(parse_point(\"3,x\"), Err(PointError::Num(_))));\n}","expect":"Ok((3, 4))\nErr(NoComma)\ntrue","hints":["`ok_or(...)` превращает `Option` в `Result`. А для `parse()?` нужен `impl From<ParseIntError> for PointError`."]},{"t":"task","md":"Функция `total` складывает числа из списка строк и возвращает `Result<i32, Box<dyn Error>>`. Если сумма больше 1000 — ошибка `\"переполнение лимита\"`.","code":"use std::error::Error;\n\nfn total(items: &[&str]) -> Result<i32, Box<dyn Error>> {\n    // твой код\n}\n\nfn main() {\n    println!(\"{:?}\", total(&[\"10\", \"20\"]).ok());\n    for bad in [&[\"10\", \"x\"][..], &[\"999\", \"2\"][..]] {\n        if let Err(e) = total(bad) {\n            println!(\"ошибка: {e}\");\n        }\n    }\n}","solution":"use std::error::Error;\n\nfn total(items: &[&str]) -> Result<i32, Box<dyn Error>> {\n    let mut sum = 0;\n    for s in items {\n        let n: i32 = s.parse()?;\n        sum += n;\n    }\n    if sum > 1000 {\n        return Err(\"переполнение лимита\".into());\n    }\n    Ok(sum)\n}\n\nfn main() {\n    println!(\"{:?}\", total(&[\"10\", \"20\"]).ok());\n    for bad in [&[\"10\", \"x\"][..], &[\"999\", \"2\"][..]] {\n        if let Err(e) = total(bad) {\n            println!(\"ошибка: {e}\");\n        }\n    }\n}","expect":"Some(30)\nошибка: invalid digit found in string\nошибка: переполнение лимита","hints":["Внутри цикла `let n: i32 = s.parse()?;` — ошибка разбора сама попадёт в коробку.","Текстовую ошибку делают так: `Err(\"переполнение лимита\".into())`."]},{"t":"recap","items":["`enum` + `Display` + `From` — полная система ошибок.","`ok_or` превращает `Option` в `Result`, чтобы использовать `?`.","`Box<dyn Error>` принимает любые ошибки и даже строки."]}],"practice":true,"goals":["Построить систему ошибок для маленькой программы"]}]},{"id":"a05","title":"Времена жизни глубже","sub":"Метки в impl, 'static, несколько меток, разбор строк без копий","lessons":[{"id":"a05-1","title":"Метки в структурах и impl","min":7,"cards":[{"t":"text","title":"Короткое напоминание","md":"Метка времени жизни `'a` ничего **не меняет** в программе. Она только **описывает** связь: «эта ссылка живёт не дольше той».\n\n```\nfn longer<'a>(a: &'a str, b: &'a str) -> &'a str {\n    if a.len() > b.len() { a } else { b }\n}\n```\nЧитается: «результат живёт, пока живы оба аргумента».\n\nЕсли забыл основы — урок первого уровня «Времена жизни».\n\n> **Аналогия:** пропуск в здание. На нём написано «действует, пока действует пропуск сопровождающего». Пропуск ничего не продлевает, он просто честно говорит срок."},{"t":"text","title":"Структура с ссылкой","md":"Если структура хранит ссылку, у неё должна быть метка:\n\n```\nstruct Highlight<'a> {\n    text: &'a str,\n}\n```\n«`Highlight` не может пережить строку, на которую смотрит».\n\nИ у `impl` тоже пишут метку — объявить её, как объявляют `<T>`:\n\n```\nimpl<'a> Highlight<'a> {\n    fn get(&self) -> &'a str { self.text }\n}\n```"},{"t":"code","code":"struct Highlight<'a> {\n    text: &'a str,\n}\n\nimpl<'a> Highlight<'a> {\n    fn new(text: &'a str) -> Self {\n        Highlight { text }\n    }\n    fn first_word(&self) -> &'a str {\n        self.text.split_whitespace().next().unwrap_or(\"\")\n    }\n}\n\nfn main() {\n    let book = String::from(\"Однажды в студёную зимнюю пору\");\n    let h = Highlight::new(&book);\n    println!(\"{}\", h.first_word());\n}","out":"Однажды","after":"`first_word` возвращает `&'a str` — кусок **исходной** книги, а не самой структуры. Он может пережить `h`, но не `book`."},{"t":"quiz","md":"Что означает `struct View<'a> { s: &'a str }`?","options":["`View` живёт ровно столько же, сколько строка","`View` не может пережить строку, на которую ссылается","Строка копируется внутрь `View`"],"answer":1,"why":["Не ровно: может меньше, но не дольше.","Верно.","Нет, внутри только ссылка."]},{"t":"fill","explain":"Сначала метку объявляют: `impl<'a>`, потом используют: `Parser<'a>`.","md":"Заполни пропуски в объявлении `impl`.","code":"struct Parser<'a> {\n    input: &'a str,\n}\n\nimpl<___> Parser<___> {\n    fn rest(&self) -> &'a str {\n        self.input\n    }\n}","answers":[["'a"],["'a"]]},{"t":"recap","items":["`'a` описывает связь сроков, а не меняет их.","Структура со ссылкой — `struct S<'a>`.","`impl<'a> S<'a>` — объявить и использовать метку."]}],"goals":["Вспомнить, зачем нужна метка `'a`","Писать `impl<'a>` для структуры со ссылкой"]},{"id":"a05-2","title":"'static: два разных смысла","min":7,"cards":[{"t":"text","title":"Смысл первый: ссылка на вечное","md":"`&'static str` — ссылка, которая действительна **всю программу**. Например, строковые литералы: они зашиты прямо в программу.\n\n```\nlet s: &'static str = \"привет\"; // текст лежит в самой программе\n```"},{"t":"text","title":"Смысл второй: тип без временных ссылок","md":"`T: 'static` в требованиях **не** значит «живёт вечно». Это значит: «внутри `T` нет ссылок на что-то временное». Такой тип можно держать сколько угодно.\n\n- `String`, `i32`, `Vec<u8>` — подходят: ссылок нет.\n- `&'static str` — подходит.\n- `&'a str` с коротким `'a` — не подходит.\n\n> **Аналогия:** «можно взять в долгий поход». Подходит то, что ни к чему не привязано: свой рюкзак — да, чужая вещь на время — нет."},{"t":"code","code":"use std::thread;\n\nfn run_later<T: Send + 'static + std::fmt::Debug>(value: T) {\n    thread::spawn(move || println!(\"в потоке: {value:?}\")).join().unwrap();\n}\n\nfn main() {\n    run_later(String::from(\"своя строка\"));  // ок: String ни на что не ссылается\n    run_later(vec![1, 2, 3]);                 // ок\n    run_later(\"литерал\");                     // ок: &'static str\n    // let local = String::from(\"x\");\n    // run_later(&local);                     // нельзя: ссылка на временное\n}","out":"в потоке: \"своя строка\"\nв потоке: [1, 2, 3]\nв потоке: \"литерал\"","after":"`thread::spawn` требует `'static`: поток может жить дольше `main`. Раскомментируй последние строки и посмотри ошибку."},{"t":"quiz","md":"Удовлетворяет ли `String` требованию `T: 'static`?","options":["Да","Нет, `String` ведь не живёт вечно","Только если строка пустая"],"answer":0,"why":["Верно. Внутри нет временных ссылок, `String` владеет своими данными.","`'static` в требовании не про вечность, а про отсутствие временных ссылок.","Содержимое не важно."]},{"t":"text","title":"Компилятор просит 'static. Что делать?","md":"Частая ситуация: «borrowed value does not live long enough… argument requires that it is borrowed for `'static`».\n\nОбычно помогает одно из:\n- передать **владение** (`String` вместо `&str`, `move` в замыкании);\n- склонировать данные;\n- обернуть в `Arc` (модуль про потоки).\n\nПисать `'static` в своих метках, чтобы «заткнуть» компилятор, почти никогда не нужно."},{"t":"recap","items":["`&'static T` — ссылка на то, что живёт всю программу (литералы).","`T: 'static` — в типе нет временных ссылок. `String`, `Vec`, числа подходят.","Просит `'static` — отдай владение или склонируй."]}],"goals":["Различать `&'static T` и `T: 'static`","Не пугаться `'static` в ошибках компилятора"]},{"id":"a05-3","title":"Правила пропуска меток","min":7,"cards":[{"t":"text","title":"Три правила","md":"Компилятор дописывает метки сам по трём правилам:\n1. Каждая ссылка-аргумент получает **свою** метку.\n2. Если ссылка-аргумент **одна** — её метка достаётся результату.\n3. Если есть `&self` или `&mut self` — результат получает метку **`self`**.\n\nЕсли по правилам не вышло — пиши метки сам."},{"t":"code","code":"// Правило 2: один аргумент-ссылка — результат живёт как он\nfn first(s: &str) -> &str {\n    &s[..1]\n}\n\nstruct Doc {\n    title: String,\n}\n\nimpl Doc {\n    // Правило 3: результат живёт как self\n    fn short(&self, n: usize) -> &str {\n        &self.title[..n]\n    }\n}\n\nfn main() {\n    println!(\"{}\", first(\"Rust\"));\n    let d = Doc { title: String::from(\"Manual\") };\n    println!(\"{}\", d.short(3));\n}","out":"R\nMan","after":"Ни одной метки, а всё работает: компилятор применил правила."},{"t":"text","title":"Когда правила не угадали","md":"Метод с `&self` возвращает кусок **другого** аргумента — правило 3 тут ошибётся:\n\n```\nimpl Doc {\n    // без меток компилятор решит, что результат живёт как self\n    fn pick<'b>(&self, other: &'b str) -> &'b str {\n        other\n    }\n}\n```\nТут метку пишут явно: результат связан с `other`, а не с `self`."},{"t":"quiz","md":"`fn f(a: &str, b: &str) -> &str` без меток. Скомпилируется?","options":["Да, по правилу 2","Нет, компилятор не знает, с чем связан результат","Да, по правилу 3"],"answer":1,"why":["Правило 2 — для **одной** ссылки, а тут их две.","Верно. Нужно `<'a>` явно.","Тут нет `self`."]},{"t":"task","md":"Функция `prefix` возвращает часть `text` длиной, которую задаёт `pattern.len()`. Расставь метки так, чтобы результат зависел только от `text`.","code":"fn prefix(text: &str, pattern: &str) -> &str {\n    &text[..pattern.len()]\n}\n\nfn main() {\n    let text = String::from(\"hello world\");\n    let p;\n    {\n        let pattern = String::from(\"hey\");\n        p = prefix(&text, &pattern);\n    }\n    println!(\"{p}\");\n}","solution":"fn prefix<'a>(text: &'a str, pattern: &str) -> &'a str {\n    &text[..pattern.len()]\n}\n\nfn main() {\n    let text = String::from(\"hello world\");\n    let p;\n    {\n        let pattern = String::from(\"hey\");\n        p = prefix(&text, &pattern);\n    }\n    println!(\"{p}\");\n}","expect":"hel","hints":["Метка нужна только у `text` и у результата: `fn prefix<'a>(text: &'a str, pattern: &str) -> &'a str`.","Если связать результат и с `pattern`, `main` не скомпилируется: `pattern` умирает раньше `println!`."]},{"t":"deep","title":"for<'a>: метка «для любой»","md":"Иногда нужно сказать: «замыкание, которое работает со ссылкой **любого** срока». Для этого есть запись `for<'a>`:\n\n```\nfn apply<F>(f: F) where F: for<'a> Fn(&'a str) -> &'a str { ... }\n```\nЧитается: «для любого `'a` функция берёт `&'a str` и возвращает `&'a str`».\n\nХорошая новость: обычно писать это не надо. `F: Fn(&str) -> &str` компилятор сам разворачивает в `for<'a>`. Но в сообщениях об ошибках эта запись иногда встречается, так что полезно её узнавать. Называется **higher-ranked trait bounds** (HRTB)."},{"t":"recap","items":["Одна ссылка на входе — результат живёт как она.","Есть `&self` — результат живёт как `self`.","Иначе — пиши метки сам и связывай результат только с тем, откуда он взят."]}],"goals":["Знать, когда метки можно не писать","Понимать, откуда берётся срок результата у методов"]},{"id":"a05-4","title":"Разбор строки без копий","min":8,"cards":[{"t":"text","title":"Зачем возвращать &str, а не String","md":"Разбираешь большой текст на слова. Можно сделать каждое слово новой `String` — это **копирование**. А можно вернуть `&str` — **окошко** в исходный текст. Копий ноль.\n\nМетки времени жизни как раз и позволяют делать такое безопасно: Rust проследит, чтобы окошки не пережили текст.\n\n> **Аналогия:** закладки в книге вместо ксерокопий страниц. Закладки ничего не весят, но без книги бесполезны."},{"t":"code","code":"struct Tokens<'a> {\n    rest: &'a str,\n}\n\nimpl<'a> Iterator for Tokens<'a> {\n    type Item = &'a str;\n    fn next(&mut self) -> Option<&'a str> {\n        let s = self.rest.trim_start();\n        if s.is_empty() {\n            return None;\n        }\n        let end = s.find(' ').unwrap_or(s.len());\n        let (word, rest) = s.split_at(end);\n        self.rest = rest;\n        Some(word)\n    }\n}\n\nfn main() {\n    let line = String::from(\"  let x  = 42 ;\");\n    let words: Vec<&str> = Tokens { rest: &line }.collect();\n    println!(\"{words:?}\");\n}","out":"[\"let\", \"x\", \"=\", \"42\", \";\"]","after":"Ни одной новой строки: каждое слово — кусочек `line`."},{"t":"text","title":"Где здесь метки","md":"- `Tokens<'a>` хранит `&'a str` — окошко в текст.\n- `type Item = &'a str` — выдаёт куски **того же** текста, а не самого итератора.\n- Поэтому `words` может жить дольше итератора — но не дольше `line`."},{"t":"quiz","md":"Почему в `Tokens` написано `type Item = &'a str`, а не просто `&str`?","options":["Нужно сказать, что слова — куски исходного текста со сроком `'a`","Так быстрее работает","Без метки слова копировались бы"],"answer":0,"why":["Верно. В ассоциированном типе метку не пропустишь.","Метки не влияют на скорость.","Копирований нет в обоих случаях — просто без метки не скомпилируется."]},{"t":"task","md":"Допиши метод `key_value`, который разбирает `\"ключ=значение\"` и возвращает пару кусков **исходной** строки.","code":"struct Line<'a> {\n    text: &'a str,\n}\n\nimpl<'a> Line<'a> {\n    fn key_value(&self) -> Option<(&'a str, &'a str)> {\n        // твой код\n    }\n}\n\nfn main() {\n    let raw = String::from(\"name=Rust\");\n    let pair = Line { text: &raw }.key_value();\n    println!(\"{pair:?}\");\n    println!(\"{:?}\", Line { text: \"без знака\" }.key_value());\n}","solution":"struct Line<'a> {\n    text: &'a str,\n}\n\nimpl<'a> Line<'a> {\n    fn key_value(&self) -> Option<(&'a str, &'a str)> {\n        let (k, v) = self.text.split_once('=')?;\n        Some((k.trim(), v.trim()))\n    }\n}\n\nfn main() {\n    let raw = String::from(\"name=Rust\");\n    let pair = Line { text: &raw }.key_value();\n    println!(\"{pair:?}\");\n    println!(\"{:?}\", Line { text: \"без знака\" }.key_value());\n}","expect":"Some((\"name\", \"Rust\"))\nNone","hints":["`split_once('=')` возвращает `Option<(&str, &str)>`. Знак `?` работает и с `Option`."]},{"t":"recap","items":["Возвращай `&'a str`, чтобы не копировать текст.","Метка в `type Item = &'a str` связывает результат с текстом, а не с итератором.","Rust не даст окошкам пережить сам текст."]}],"goals":["Написать парсер, который возвращает куски исходной строки","Понять, почему это быстро"]},{"id":"a05-p","title":"Практика: времена жизни","min":12,"cards":[{"t":"task","md":"Структура `Longest` запоминает самое длинное слово из уже увиденных. Расставь метки, чтобы код скомпилировался.","code":"struct Longest {\n    best: &str,\n}\n\nimpl Longest {\n    fn see(&mut self, w: &str) {\n        if w.len() > self.best.len() {\n            self.best = w;\n        }\n    }\n}\n\nfn main() {\n    let text = String::from(\"кот гиппопотам ёж\");\n    let mut l = Longest { best: \"\" };\n    for w in text.split(' ') {\n        l.see(w);\n    }\n    println!(\"{}\", l.best);\n}","solution":"struct Longest<'a> {\n    best: &'a str,\n}\n\nimpl<'a> Longest<'a> {\n    fn see(&mut self, w: &'a str) {\n        if w.len() > self.best.len() {\n            self.best = w;\n        }\n    }\n}\n\nfn main() {\n    let text = String::from(\"кот гиппопотам ёж\");\n    let mut l = Longest { best: \"\" };\n    for w in text.split(' ') {\n        l.see(w);\n    }\n    println!(\"{}\", l.best);\n}","expect":"гиппопотам","hints":["Структура: `struct Longest<'a> { best: &'a str }`, и `impl<'a> Longest<'a>`.","`w` будет сохранено в `best`, значит у него тот же срок: `w: &'a str`."]},{"t":"task","md":"Функция `split_name` делит `\"Имя Фамилия\"` на две части без копирования. Напиши её сигнатуру и тело.","code":"// твой код\n\nfn main() {\n    let full = String::from(\"Ада Лавлейс\");\n    let (first, last) = split_name(&full);\n    println!(\"{last}, {first}\");\n}","solution":"fn split_name(full: &str) -> (&str, &str) {\n    full.split_once(' ').unwrap_or((full, \"\"))\n}\n\nfn main() {\n    let full = String::from(\"Ада Лавлейс\");\n    let (first, last) = split_name(&full);\n    println!(\"{last}, {first}\");\n}","expect":"Лавлейс, Ада","hints":["Аргумент-ссылка один, поэтому метки можно не писать: `fn split_name(full: &str) -> (&str, &str)`.","`split_once(' ')` вернёт `Option`. Если пробела нет — `unwrap_or((full, \"\"))`."]},{"t":"task","md":"Функция `pick` берёт два текста и флаг. Если флаг `true` — возвращает первый, иначе второй. Расставь метки.","code":"fn pick(a: &str, b: &str, first: bool) -> &str {\n    if first { a } else { b }\n}\n\nfn main() {\n    let x = String::from(\"левый\");\n    let y = String::from(\"правый\");\n    println!(\"{}\", pick(&x, &y, false));\n}","solution":"fn pick<'a>(a: &'a str, b: &'a str, first: bool) -> &'a str {\n    if first { a } else { b }\n}\n\nfn main() {\n    let x = String::from(\"левый\");\n    let y = String::from(\"правый\");\n    println!(\"{}\", pick(&x, &y, false));\n}","expect":"правый","hints":["Результат может быть любым из двух, поэтому оба получают одну метку `'a`."]},{"t":"recap","items":["Структура, которая хранит ссылку, — с меткой.","Сохраняешь аргумент в поле — у аргумента та же метка.","Результат «одно из двух» — одна общая метка."]}],"practice":true,"goals":["Расставить метки в нескольких типичных местах"]}]},{"id":"a06","title":"Память без сюрпризов","sub":"Drop, mem::take, Cow и Weak","lessons":[{"id":"a06-1","title":"Drop: что происходит в конце","min":7,"cards":[{"t":"text","title":"Уборка по расписанию","md":"Когда владелец уходит из области видимости, Rust **удаляет** значение. Перед этим он вызывает метод `drop` из трейта `Drop`, если тот есть.\n\nТак `String` освобождает память, файл закрывается, а замок отпускается. Сам ты `drop` не вызываешь — это делает Rust.\n\n> **Аналогия:** выезд из гостиницы. Ты просто уходишь, а горничная убирает номер. Свой `Drop` — это записка горничной: «полейте, пожалуйста, цветок»."},{"t":"code","code":"struct Noisy(&'static str);\n\nimpl Drop for Noisy {\n    fn drop(&mut self) {\n        println!(\"убираю {}\", self.0);\n    }\n}\n\nfn main() {\n    let _a = Noisy(\"а\");\n    let _b = Noisy(\"б\");\n    {\n        let _c = Noisy(\"в\");\n        println!(\"конец блока\");\n    }\n    println!(\"конец main\");\n}","out":"конец блока\nубираю в\nконец main\nубираю б\nубираю а","after":"Переменные удаляются в **обратном** порядке: последняя созданная — первой. Как тарелки в стопке."},{"t":"text","title":"Убрать раньше: drop(x)","md":"Иногда значение надо убрать **до** конца блока: закрыть файл, отпустить замок. Для этого есть функция `drop(x)`:\n\n```\nlet lock = data.lock().unwrap();\n// работа с данными\ndrop(lock); // отпустили замок сейчас, а не в конце функции\n```\n`drop(x)` просто забирает `x` себе и сразу заканчивается. Вызвать `x.drop()` напрямую Rust не разрешит — чтобы не убрать одно и то же дважды."},{"t":"quiz","md":"`let a = ...; let b = ...;` — в каком порядке их удалит Rust в конце блока?","options":["Сначала `a`, потом `b`","Сначала `b`, потом `a`","Одновременно"],"answer":1,"why":["Наоборот.","Верно. Обратный порядок создания.","Порядок всегда строгий."]},{"t":"quiz","md":"Как убрать значение `x` раньше конца блока?","options":["`x.drop()`","`drop(x)`","`x = null`"],"answer":1,"why":["Так Rust не разрешает.","Верно.","В Rust нет `null`."]},{"t":"deep","title":"Порядок полей и почему _ опасен","md":"Поля структуры удаляются в порядке **объявления** — сверху вниз. Это редко важно, но иногда одно поле должно умереть раньше другого (например, поток раньше канала). Тогда меняют порядок полей.\n\nЕщё одна ловушка: `let _ = значение;` удаляет значение **сразу**, потому что `_` — это не переменная, а «выбросить». А `let _guard = значение;` держит его до конца блока. С замками разница огромная:\n\n```\nlet _ = mutex.lock(); // замок тут же отпущен!\nlet _g = mutex.lock(); // замок держится до конца блока\n```"},{"t":"task","md":"Сделай `Drop` для `Guard`, чтобы он печатал `выход: <имя>`. Проверь порядок.","code":"struct Guard {\n    name: String,\n}\n\n// твой код\n\nfn main() {\n    let _outer = Guard { name: String::from(\"внешний\") };\n    let inner = Guard { name: String::from(\"внутренний\") };\n    drop(inner);\n    println!(\"работаю\");\n}","solution":"struct Guard {\n    name: String,\n}\n\nimpl Drop for Guard {\n    fn drop(&mut self) {\n        println!(\"выход: {}\", self.name);\n    }\n}\n\nfn main() {\n    let _outer = Guard { name: String::from(\"внешний\") };\n    let inner = Guard { name: String::from(\"внутренний\") };\n    drop(inner);\n    println!(\"работаю\");\n}","expect":"выход: внутренний\nработаю\nвыход: внешний","hints":["`impl Drop for Guard { fn drop(&mut self) { println!(\"выход: {}\", self.name); } }`."]},{"t":"recap","items":["`Drop::drop` вызывается сам, когда значение удаляется.","Переменные удаляются в обратном порядке.","`drop(x)` — убрать раньше."]}],"goals":["Узнать, в каком порядке удаляются значения","Написать свой `Drop`"]},{"id":"a06-2","title":"mem::take и mem::replace","min":7,"cards":[{"t":"text","title":"Проблема: забрать из-под ссылки","md":"У тебя `&mut self`, а нужно **забрать** поле `self.items` себе (например, отдать наружу). Просто `let v = self.items;` нельзя: нельзя оставить структуру с «дыркой».\n\nРешение — поменять значение на другое:\n- `std::mem::take(&mut x)` — забрать `x`, а на его место положить пустое (значение по умолчанию).\n- `std::mem::replace(&mut x, новое)` — забрать `x`, на место положить `новое`.\n- `std::mem::swap(&mut a, &mut b)` — поменять местами.\n\n> **Аналогия:** подменить вазу на столе. Забираешь старую, тут же ставишь новую — стол ни секунды не пустой."},{"t":"code","code":"use std::mem;\n\nstruct Inbox {\n    messages: Vec<String>,\n}\n\nimpl Inbox {\n    fn drain_all(&mut self) -> Vec<String> {\n        mem::take(&mut self.messages) // забрали, на месте пустой Vec\n    }\n}\n\nfn main() {\n    let mut inbox = Inbox { messages: vec![String::from(\"привет\"), String::from(\"как дела\")] };\n    let got = inbox.drain_all();\n    println!(\"забрали {}: {:?}\", got.len(), got);\n    println!(\"в ящике: {}\", inbox.messages.len());\n\n    let mut mode = String::from(\"день\");\n    let old = mem::replace(&mut mode, String::from(\"ночь\"));\n    println!(\"{old} -> {mode}\");\n}","out":"забрали 2: [\"привет\", \"как дела\"]\nв ящике: 0\nдень -> ночь","after":"Никаких `clone()`: строки просто переехали."},{"t":"text","title":"take и Option","md":"С `Option` есть удобный метод `take()`: забирает значение и оставляет `None`.\n\n```\nlet mut slot: Option<String> = Some(String::from(\"ключ\"));\nlet k = slot.take(); // k = Some(\"ключ\"), slot = None\n```\nТак часто устроены «одноразовые» вещи: забрал — и больше нет."},{"t":"quiz","md":"Что останется в `v` после `let x = std::mem::take(&mut v);`, если `v: Vec<i32>`?","options":["Пустой вектор","Ничего, `v` удалён","Копия старого вектора"],"answer":0,"why":["Верно. `take` кладёт значение по умолчанию.","`v` жив, просто пуст.","Копий нет, всё переехало в `x`."]},{"t":"task","md":"Метод `finish` должен вернуть накопленный текст и очистить буфер. Используй `mem::take`.","code":"use std::mem;\n\nstruct Writer {\n    buf: String,\n}\n\nimpl Writer {\n    fn write(&mut self, s: &str) {\n        self.buf.push_str(s);\n    }\n    fn finish(&mut self) -> String {\n        // твой код\n    }\n}\n\nfn main() {\n    let mut w = Writer { buf: String::new() };\n    w.write(\"Раз, \");\n    w.write(\"два\");\n    let text = w.finish();\n    println!(\"{text}\");\n    println!(\"пусто: {}\", w.buf.is_empty());\n}","solution":"use std::mem;\n\nstruct Writer {\n    buf: String,\n}\n\nimpl Writer {\n    fn write(&mut self, s: &str) {\n        self.buf.push_str(s);\n    }\n    fn finish(&mut self) -> String {\n        mem::take(&mut self.buf)\n    }\n}\n\nfn main() {\n    let mut w = Writer { buf: String::new() };\n    w.write(\"Раз, \");\n    w.write(\"два\");\n    let text = w.finish();\n    println!(\"{text}\");\n    println!(\"пусто: {}\", w.buf.is_empty());\n}","expect":"Раз, два\nпусто: true","hints":["Одна строка: `mem::take(&mut self.buf)`."]},{"t":"recap","items":["`mem::take` — забрать и оставить пустое.","`mem::replace` — забрать и оставить своё.","`Option::take()` — забрать и оставить `None`."]}],"goals":["Достать значение из `&mut` без клонирования","Знать `take`, `replace` и `swap`"]},{"id":"a06-3","title":"Cow: копировать, только если надо","min":7,"cards":[{"t":"text","title":"Иногда менять, иногда нет","md":"Функция чистит текст: убирает лишние пробелы. Часто текст **уже** чистый — копировать незачем. Но иногда менять надо — и тогда нужна новая `String`.\n\n`Cow` (clone on write, «копировать при записи») — это `enum` из двух вариантов:\n- `Cow::Borrowed(&str)` — просто ссылка, ничего не копировали;\n- `Cow::Owned(String)` — пришлось сделать свою копию.\n\n> **Аналогия:** берёшь книгу у друга. Если только читаешь — возвращаешь как есть. Захотел подчеркнуть — покупаешь свою."},{"t":"code","code":"use std::borrow::Cow;\n\nfn no_tabs(s: &str) -> Cow<'_, str> {\n    if s.contains('\\t') {\n        Cow::Owned(s.replace('\\t', \"    \"))\n    } else {\n        Cow::Borrowed(s)\n    }\n}\n\nfn main() {\n    for line in [\"clean line\", \"a\\tb\"] {\n        let r = no_tabs(line);\n        let kind = match r {\n            Cow::Borrowed(_) => \"без копии\",\n            Cow::Owned(_) => \"копия\",\n        };\n        println!(\"{kind}: {r}\");\n    }\n}","out":"без копии: clean line\nкопия: a    b","after":"`Cow` печатается и используется как обычная строка. Разница только в том, была ли копия."},{"t":"text","title":"Где Cow встречается","md":"- `String::from_utf8_lossy` возвращает `Cow<str>`: если байты правильные — без копии.\n- В функциях, которые «обычно ничего не меняют».\n- `.into_owned()` превращает любой `Cow` в своё значение, когда нужно точно владеть."},{"t":"quiz","md":"Функция вернула `Cow::Borrowed(s)`. Было ли копирование?","options":["Да, `Cow` всегда копирует","Нет, это просто ссылка на исходные данные","Неизвестно"],"answer":1,"why":["Копирует только при записи.","Верно.","Вариант `Borrowed` прямо говорит: копии нет."]},{"t":"task","md":"Функция `shout` возвращает текст как есть, если он уже весь в верхнем регистре, иначе — новую строку в верхнем регистре. Используй `Cow`.","code":"use std::borrow::Cow;\n\nfn shout(s: &str) -> Cow<'_, str> {\n    // твой код\n}\n\nfn main() {\n    for s in [\"HELLO\", \"Hi\"] {\n        let r = shout(s);\n        println!(\"{} {}\", r, matches!(r, Cow::Borrowed(_)));\n    }\n}","solution":"use std::borrow::Cow;\n\nfn shout(s: &str) -> Cow<'_, str> {\n    if s.chars().all(|c| !c.is_lowercase()) {\n        Cow::Borrowed(s)\n    } else {\n        Cow::Owned(s.to_uppercase())\n    }\n}\n\nfn main() {\n    for s in [\"HELLO\", \"Hi\"] {\n        let r = shout(s);\n        println!(\"{} {}\", r, matches!(r, Cow::Borrowed(_)));\n    }\n}","expect":"HELLO true\nHI false","hints":["Проверка: нет ни одной строчной буквы — `s.chars().all(|c| !c.is_lowercase())`."]},{"t":"recap","items":["`Cow` = либо ссылка (`Borrowed`), либо своё значение (`Owned`).","Удобно, когда изменения нужны редко.","`.into_owned()` — получить своё значение в любом случае."]}],"goals":["Понять, что такое `Cow`","Возвращать то ссылку, то новую строку из одной функции"]},{"id":"a06-4","title":"Weak: ссылка, которая не держит","min":8,"cards":[{"t":"text","title":"Утечка через круг","md":"`Rc` удаляет значение, когда счётчик владельцев доходит до нуля. А если A держит B, а B держит A? Счётчики никогда не станут нулём — память не освободится. Это **утечка**.\n\n> **Аналогия:** двое держат друг друга за руки и ждут, пока другой отпустит первым. Стоят вечно."},{"t":"text","title":"Weak — смотреть, не держа","md":"`Weak` — слабая ссылка. Она знает, где значение, но **не продлевает** ему жизнь.\n- `Rc::downgrade(&rc)` — сделать `Weak` из `Rc`.\n- `weak.upgrade()` — попробовать получить `Rc`. Вернёт `Option`: `None`, если значение уже удалено.\n\nПравило: **родитель держит детей через `Rc`, ребёнок смотрит на родителя через `Weak`**."},{"t":"code","code":"use std::cell::RefCell;\nuse std::rc::{Rc, Weak};\n\nstruct Node {\n    name: String,\n    parent: RefCell<Weak<Node>>,\n    children: RefCell<Vec<Rc<Node>>>,\n}\n\nfn main() {\n    let root = Rc::new(Node {\n        name: String::from(\"корень\"),\n        parent: RefCell::new(Weak::new()),\n        children: RefCell::new(vec![]),\n    });\n    let leaf = Rc::new(Node {\n        name: String::from(\"лист\"),\n        parent: RefCell::new(Weak::new()),\n        children: RefCell::new(vec![]),\n    });\n    *leaf.parent.borrow_mut() = Rc::downgrade(&root);\n    root.children.borrow_mut().push(Rc::clone(&leaf));\n\n    let p = leaf.parent.borrow().upgrade();\n    println!(\"родитель листа: {}\", p.map(|n| n.name.clone()).unwrap_or_default());\n    println!(\"детей у корня: {}\", root.children.borrow().len());\n    println!(\"сильных у корня: {}, слабых: {}\", Rc::strong_count(&root), Rc::weak_count(&root));\n}","out":"родитель листа: корень\nдетей у корня: 1\nсильных у корня: 1, слабых: 1","after":"У корня один сильный владелец (`root`) и одна слабая ссылка (от листа). Когда `root` уйдёт — корень удалится, цикла нет."},{"t":"code","md":"`upgrade` возвращает `None`, если значение уже удалено:","code":"use std::rc::Rc;\n\nfn main() {\n    let strong = Rc::new(5);\n    let weak = Rc::downgrade(&strong);\n    println!(\"{:?}\", weak.upgrade());\n    drop(strong);\n    println!(\"{:?}\", weak.upgrade());\n}","out":"Some(5)\nNone"},{"t":"quiz","md":"В дереве ребёнок хранит ссылку на родителя. Какую?","options":["`Rc<Node>`","`Weak<Node>`","`Box<Node>`"],"answer":1,"why":["Получится цикл: родитель держит ребёнка, ребёнок — родителя.","Верно. Ребёнок смотрит, но не держит.","`Box` — единственный владелец, у родителя уже есть владелец."]},{"t":"fill","explain":"`downgrade` — сделать слабую ссылку, `upgrade` — попытаться снова получить сильную.","md":"Заполни пропуски: получи `Weak` из `Rc`, а потом попробуй вернуть `Rc`.","code":"let strong = Rc::new(String::from(\"данные\"));\nlet weak = Rc::___(&strong);\nif let Some(s) = weak.___() {\n    println!(\"{s}\");\n}","answers":[["downgrade"],["upgrade"]]},{"t":"recap","items":["Круг из `Rc` — утечка: счётчики не дойдут до нуля.","`Weak` смотрит, но не держит. `upgrade()` → `Option<Rc>`.","Родитель → ребёнок: `Rc`. Ребёнок → родитель: `Weak`."]}],"goals":["Понять, как `Rc` может создать утечку памяти","Разорвать цикл с помощью `Weak`"]},{"id":"a06-p","title":"Практика: память","min":12,"cards":[{"t":"task","md":"Состояние светофора меняется методом `next`, который возвращает **старое** состояние. Используй `mem::replace`.","code":"use std::mem;\n\n#[derive(Debug)]\nenum Light {\n    Red,\n    Green,\n    Yellow,\n}\n\nstruct Traffic {\n    light: Light,\n}\n\nimpl Traffic {\n    fn next(&mut self) -> Light {\n        let new = match self.light {\n            Light::Red => Light::Green,\n            Light::Green => Light::Yellow,\n            Light::Yellow => Light::Red,\n        };\n        // твой код\n    }\n}\n\nfn main() {\n    let mut t = Traffic { light: Light::Red };\n    println!(\"{:?}\", t.next());\n    println!(\"{:?}\", t.next());\n    println!(\"{:?}\", t.light);\n}","solution":"use std::mem;\n\n#[derive(Debug)]\nenum Light {\n    Red,\n    Green,\n    Yellow,\n}\n\nstruct Traffic {\n    light: Light,\n}\n\nimpl Traffic {\n    fn next(&mut self) -> Light {\n        let new = match self.light {\n            Light::Red => Light::Green,\n            Light::Green => Light::Yellow,\n            Light::Yellow => Light::Red,\n        };\n        mem::replace(&mut self.light, new)\n    }\n}\n\nfn main() {\n    let mut t = Traffic { light: Light::Red };\n    println!(\"{:?}\", t.next());\n    println!(\"{:?}\", t.next());\n    println!(\"{:?}\", t.light);\n}","expect":"Red\nGreen\nYellow","hints":["`mem::replace(&mut self.light, new)` положит `new` и вернёт старое."]},{"t":"task","md":"Счётчик `Tracker` при удалении печатает, сколько раз его вызывали. Допиши `Drop`.","code":"struct Tracker {\n    calls: u32,\n}\n\nimpl Tracker {\n    fn hit(&mut self) {\n        self.calls += 1;\n    }\n}\n\n// твой код\n\nfn main() {\n    let mut t = Tracker { calls: 0 };\n    t.hit();\n    t.hit();\n    t.hit();\n    println!(\"готово\");\n}","solution":"struct Tracker {\n    calls: u32,\n}\n\nimpl Tracker {\n    fn hit(&mut self) {\n        self.calls += 1;\n    }\n}\n\nimpl Drop for Tracker {\n    fn drop(&mut self) {\n        println!(\"вызовов: {}\", self.calls);\n    }\n}\n\nfn main() {\n    let mut t = Tracker { calls: 0 };\n    t.hit();\n    t.hit();\n    t.hit();\n    println!(\"готово\");\n}","expect":"готово\nвызовов: 3","hints":["Сообщение появится после `готово`: `t` удаляется в конце `main`."]},{"t":"task","md":"Функция `normalize` заменяет `ё` на `е`. Если `ё` нет — без копирования. Посчитай, сколько строк пришлось скопировать.","code":"use std::borrow::Cow;\n\nfn normalize(s: &str) -> Cow<'_, str> {\n    // твой код\n}\n\nfn main() {\n    let words = [\"ёжик\", \"кот\", \"всё\", \"дом\"];\n    let mut copies = 0;\n    for w in words {\n        let n = normalize(w);\n        if let Cow::Owned(_) = n {\n            copies += 1;\n        }\n        print!(\"{n} \");\n    }\n    println!();\n    println!(\"копий: {copies}\");\n}","solution":"use std::borrow::Cow;\n\nfn normalize(s: &str) -> Cow<'_, str> {\n    if s.contains('ё') {\n        Cow::Owned(s.replace('ё', \"е\"))\n    } else {\n        Cow::Borrowed(s)\n    }\n}\n\nfn main() {\n    let words = [\"ёжик\", \"кот\", \"всё\", \"дом\"];\n    let mut copies = 0;\n    for w in words {\n        let n = normalize(w);\n        if let Cow::Owned(_) = n {\n            copies += 1;\n        }\n        print!(\"{n} \");\n    }\n    println!();\n    println!(\"копий: {copies}\");\n}","expect":"ежик кот все дом\nкопий: 2","hints":["`s.contains('ё')` — проверка, `s.replace('ё', \"е\")` — новая строка."]},{"t":"recap","items":["`mem::replace` — сменить состояние и вернуть старое.","`Drop` — код «на выходе».","`Cow` — копировать только то, что меняется."]}],"practice":true,"goals":["Применить `Drop`, `mem::replace`, `Cow` и `Weak`"]}]}],"glossary":[]};
